/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A37 staging · frozen manifest fused–geophysical (80 lemmas). */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase()}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[c],mistakes:[m],quiz:qs});
P('fused','fused 是 fuse 的过去分词形容词；fuse 经法语与拉丁语 fundere“倾注、熔化”发展而来，可指熔合或紧密结合成一体。',C('fused.s1','材料加工','The fused glass formed a single smooth panel after the heated edges softened and joined under pressure.','受热边缘软化并在压力下接合后，熔融玻璃形成了一整块光滑面板。','The fused glass formed a single smooth panel / after the heated edges softened and joined / under pressure.','fused 修饰 glass，说明材料经加热接合；after 从句交代形成过程。','加热后边缘软化并合为一体，符合熔合义 s1。'),M('The fused glass consisted of two separate cold sheets that never touched or joined.','The unfused glass consisted of two separate cold sheets that never touched or joined.','彼此分离、未经接合的玻璃不属于 fused。'),[Q('fused',1,1,'Two metals that are fused have been?','joined into one mass, often by heat','kept apart by a layer of air','measured without being changed','fused 表示熔合或结合成一体。'),Q('fused',2,2,'If a device has a fused fuse, the fuse has?','melted and interrupted the electrical current','been replaced by a larger battery','started producing extra electricity','fused.s2 指保险丝熔断。'),Q('fused',3,1,'Which result is fused?','two heated glass edges become one continuous piece','two tiles remain loose in separate boxes','a sheet is measured with a ruler','加热并接合成连续整体是融合结果。'),Q('fused',4,1,'The closest opposite of fused materials is?','separate materials','joined materials','combined materials','分离与融合相反。')]);
P('futility','futility 由 futile 加名词后缀 -ity 构成；futile 经法语与拉丁语 futtilis“易漏、无用”发展，表示努力无益或不可能成功。',C('futility.s1','工程决策','After the third failed repair, the team recognized the futility of patching the cracked pipe and replaced the damaged section instead.','第三次维修失败后，团队认识到继续修补裂管徒劳无益，于是直接更换了损坏部分。','After the third failed repair / the team recognized the futility of patching the cracked pipe / and replaced the damaged section instead.','futility of + 动名词说明无益之举；instead 表明改用更有效的方案。','多次失败表明继续修补无法奏效，符合徒劳义。'),M('They celebrated the futility of the plan because it had already succeeded exactly as intended.','They celebrated the success of the plan because it had already worked exactly as intended.','已经按预期成功的计划不应称为 futility。'),[Q('futility',1,1,'The futility of repeating a failed test means repetition is?','unlikely to achieve anything useful','guaranteed to produce a new answer','required by every scientific method','futility 表示徒劳无益。'),Q('futility',2,1,'A worker recognizes the futility of arguing when?','the decision is final and no evidence can change it','the manager asks for relevant evidence','the discussion has not yet begun','明知争辩不可能改变结果而继续争论是徒劳。'),Q('futility',3,1,'Which phrase is natural?','the futility of the search','the futility at the searching','the futility for searched','futility 常与 of 连用。'),Q('futility',4,1,'A close contrast to futility is?','effectiveness','pointlessness','uselessness','effectiveness 表示有效、有成效。')]);
P('futurism','futurism 由 future 加 -ism 构成，是 20 世纪初兴起的艺术与文学运动名称，强调现代科技、速度与新形式。',C('futurism.s1','艺术史','The museum’s Futurism gallery displayed paintings of speeding trains and overlapping city lights to convey the movement’s fascination with modern technology.','博物馆的未来主义展厅展出了疾驰列车和重叠城市灯光的画作，呈现该运动对现代科技的迷恋。','The museum’s Futurism gallery displayed paintings / of speeding trains and overlapping city lights / to convey the movement’s fascination / with modern technology.','Futurism 作专名通常大写；to convey 说明展品表现的艺术理念。','作品赞颂速度、城市和现代科技，符合未来主义特征。'),M('Futurism rejected modern machines and insisted that artists imitate only ancient rural life.','Futurism celebrated modern machines and explored new forms instead of limiting art to ancient rural life.','拒绝现代机器与未来主义颂扬科技的特点相反。'),[Q('futurism',1,1,'Futurism is chiefly a movement in?','modern art and literature','medieval law','classical ship navigation','Futurism 是艺术与文学运动。'),Q('futurism',2,1,'A Futurist painting might emphasize?','speeding machines and the energy of modern cities','a perfectly still medieval village only','a scientific table with no artistic choices','速度和现代城市是未来主义常见主题。'),Q('futurism',3,1,'Why is technology central to Futurism?','the movement glorified modern life and its machines','the movement banned all depictions of cities','artists used it only to restore ancient pottery','未来主义赞颂现代科技和生活。'),Q('futurism',4,1,'Which idea contrasts with Futurism’s stated focus?','rejecting every feature of modern technology','experimenting with new artistic forms','depicting motion and urban change','全面排斥现代科技与该运动理念相反。')]);
P('fuze','fuze 是 fuse 的另一种拼写，尤见于军事技术，指使炸弹或炮弹在特定条件下点火、起爆的装置。',C('fuze.s1','军械安全','The technicians inspected the shell’s fuze remotely and kept the device untouched until the bomb-disposal team secured the area.','技术人员远程检查炮弹引信，在拆弹小组控制现场前没有触碰装置。','The technicians inspected the shell’s fuze remotely / and kept the device untouched / until the bomb-disposal team secured the area.','fuze 指起爆或点火机构；remotely 与 untouched 表明安全处置方式。','炮弹上触发点火的机构即引信。'),M('The shell’s fuze was a harmless label that could not ignite or trigger anything.','The shell’s fuze was the mechanism designed to trigger its ignition.','引信的功能是触发点火，并非单纯标签。'),[Q('fuze',1,1,'A shell’s fuze is the mechanism that?','triggers ignition or detonation','measures the shell’s color','stores the crew’s written orders','fuze 指引信或起爆装置。'),Q('fuze',2,1,'Why should an unexploded device’s fuze be handled by specialists?','it may trigger the device','it is a decorative metal ring','it contains a map of the area','引信可能触发爆炸，需专业处置。'),Q('fuze',3,1,'In military writing, fuze is a spelling variant of?','fuse','fuss','fusebox','fuze 与 fuse 可作拼写变体。'),Q('fuze',4,1,'A fuze differs from a safety label because a fuze?','is part of the device’s ignition mechanism','only names the device’s owner','cannot affect how the device operates','引信属于装置的触发机构。')]);
P('fuzzy','fuzzy 由 fuzz 加 -y 构成，可指表面覆有细软绒毛、图像或声音模糊，也可指想法或逻辑含糊不精确。',C('fuzzy.s2','图像质量','The old security camera produced a fuzzy image, so the technician cleaned the lens before deciding whether the number plate was readable.','旧监控摄像头拍出的图像模糊，因此技术人员先清洁镜头，再判断车牌是否可读。','The old security camera produced a fuzzy image / so the technician cleaned the lens / before deciding whether the number plate was readable.','fuzzy 修饰 image，指轮廓不清；before 引出改善图像后的判断。','车牌难以辨认说明图像清晰度不足，符合 s2。'),M('The fuzzy photograph showed every letter sharply and made the plate number perfectly clear.','The sharp photograph showed every letter clearly and made the plate number easy to read.','字母清晰可辨与 fuzzy image（模糊图像）相反。'),[Q('fuzzy',1,1,'A fuzzy blanket feels?','soft and covered with short fibers','smooth like polished glass','sharp enough to cut paper','fuzzy 可表示表面绒毛柔软。'),Q('fuzzy',2,2,'A fuzzy image is difficult to use because it is?','unclear in shape or detail','too bright to contain any colors','made entirely of sound','图像模糊、细节不清是 s2。'),Q('fuzzy',3,3,'A fuzzy definition of a rule is?','vague and imprecise','supported by exact measurements','clear enough to apply consistently','定义含糊不精确对应 s3。'),Q('fuzzy',4,2,'Which camera result is fuzzy?','the letters blur together and cannot be read','each letter is crisp at full zoom','the camera records no image at all','字母轮廓混在一起说明影像模糊。')]);
P('gabble','gabble 可能源于模仿含混急促说话的声音，可作动词表示说话过快而难懂、急促说出话语，也可作名词指含混快语。',C('gabble.s1','沟通场景','The children began to gabble over one another after the bell rang, making it impossible for the substitute teacher to understand the instructions.','铃声响后，孩子们开始七嘴八舌地急促说话，代课老师根本听不懂他们的话。','The children began to gabble over one another / after the bell rang / making it impossible / for the substitute teacher to understand the instructions.','gabble over one another 表示彼此抢话、说得含混；making 说明结果。','孩子们语速快且互相打断，导致难以理解，符合动词义。'),M('The witness gabbled each sentence slowly and distinctly so that every listener could follow it.','The witness spoke each sentence slowly and distinctly so that every listener could follow it.','缓慢清晰表达与 gabble 的急促含混相反。'),[Q('gabble',1,1,'To gabble is to speak?','quickly and unclearly','slowly with careful pauses','silently without forming words','gabble 指急促而不清楚地说话。'),Q('gabble',2,2,'A nervous child gabbled the answer when the child?','said it too fast for listeners to follow','wrote it neatly on the board','waited quietly for a turn','急促说出话语体现 s2。'),Q('gabble',3,3,'The noun gabble refers to?','fast, hard-to-understand talk','a written legal promise','a precise temperature reading','名词 gabble 指含混快语。'),Q('gabble',4,1,'Which response is gabbling?','rushing through words until the audience asks for repetition','speaking slowly into a microphone','pausing so each instruction is understood','匆忙说到听众要求重复说明话语含混。')]);
P('gage','gage 与 gauge 有历史拼写关联；名词 gage 可指抵押或挑战的信物，动词则表示精确测量或估计。',C('gage.s2','仪器读数','To gage the tire pressure accurately, the mechanic used a calibrated meter and compared its reading with the recommended range.','为了准确测量轮胎气压，修理工使用校准过的仪表，并把读数与建议范围比较。','To gage the tire pressure accurately / the mechanic used a calibrated meter / and compared its reading with the recommended range.','gage 在此作动词的同源名词用法，意为测量仪器；pressure gage 可作 pressure gauge 的拼写形式。','仪器用来测量轮胎压力，体现计量义。'),M('The mechanic gaged the tire pressure by ignoring the meter and guessing a random number.','The mechanic estimated the tire pressure by checking the meter rather than guessing.','忽略仪表而随意猜数不是精确计量。'),[Q('gage',1,1,'In an old story, throwing down a gage could mean?','offering a token as a challenge or pledge','measuring a room’s temperature','planting grain in a field','名词 gage 可指挑战信物或抵押物。'),Q('gage',2,2,'To gage a liquid’s depth is to?','measure or estimate it','deny that it exists','decorate its surface','动词 gage 表示测量或估计。'),Q('gage',3,1,'To gage pressure precisely, an engineer may?','check it with a calibrated instrument','store a written oath','soften a piece of metal','计量表用于测量压力。'),Q('gage',4,1,'Which context uses gage as a challenge token?','The knight cast down his glove as a gage.','The technician read the gage to check pressure.','The farmer gaged the field’s length.','投下手套作为挑战信物体现历史名词义。')]);
P('gaily','gaily 由 gay 加副词后缀 -ly 构成，此处 gay 取“快乐、明亮”的传统义，表示愉快地或色彩鲜艳地；需按语境理解。',C('gaily.s1','节日装饰','The shop windows were gaily decorated with paper lanterns, bright ribbons, and hand-painted signs for the spring festival.','商店橱窗装点得鲜艳喜庆，挂着纸灯笼、亮色丝带和为春季节庆手绘的招牌。','The shop windows were gaily decorated / with paper lanterns, bright ribbons, / and hand-painted signs / for the spring festival.','gaily 修饰 decorated，说明装饰方式欢快鲜艳。','灯笼和彩带营造明快喜庆的装饰效果，符合 gaily。'),M('The room was gaily lit, with every lamp switched off and all decorations removed.','The room was dark and bare, with every lamp switched off and all decorations removed.','灯全关且无装饰的房间不可能被称为 gaily lit。'),[Q('gaily',1,1,'A gaily decorated hall looks?','bright, cheerful, and colorful','empty and completely dark','formal but without any decoration','gaily 可表示欢快鲜艳地。'),Q('gaily',2,1,'Which sentence uses gaily naturally?','Children gaily waved flags along the parade route.','The alarm gaily warned residents of immediate danger.','The stone gaily weighed exactly two tons.','欢快挥舞旗帜符合 gaily 的快乐义。'),Q('gaily',3,1,'A gaily colored kite is?','brightly and cheerfully colored','painted in a single dull gray','invisible because it has no color','明亮鲜艳的颜色可用 gaily 描述。'),Q('gaily',4,1,'In “the banners fluttered gaily,” gaily suggests they moved?','in a lively, cheerful way','with a measured weight','in complete silence underground','副词表达轻快欢乐的感觉。')]);
P('gainful','gainful 由 gain 加 -ful 构成，主要形容能带来报酬或经济收益的工作、职业或活动。',C('gainful.s1','就业与收入','After months of training, Omar found gainful employment repairing medical equipment for a regional clinic.','经过数月培训，奥马尔找到了一份有报酬的工作，为地区诊所维修医疗设备。','After months of training / Omar found gainful employment / repairing medical equipment / for a regional clinic.','gainful employment 是常见搭配，指有薪工作；repairing 补充职业内容。','维修工作带来工资收入，符合 s1。'),M('She called the unpaid volunteer post gainful employment even though it produced no wages or financial benefit.','She called the unpaid volunteer post meaningful service even though it produced no wages or financial benefit.','没有报酬的志愿岗位不能称为 gainful employment。'),[Q('gainful',1,1,'Gainful employment is work that?','provides pay or income','requires no effort and no benefit','is performed only as a hobby','gainful work 尤指有报酬的工作。'),Q('gainful',2,2,'A gainful investment is one that?','produces money or another advantage','loses value in every possible case','has no outcome of any kind','s2 指带来收益或好处。'),Q('gainful',3,1,'Which activity is most clearly gainful employment?','a paid job maintaining hospital equipment','an unpaid visit to a friend','a hobby done once with no reward','有薪工作是 gainful employment。'),Q('gainful',4,1,'The closest contrast to gainful work is?','unpaid work','profitable work','remunerative employment','unpaid 与有报酬相反。')]);
P('gainsay','gainsay 经中古英语由 gain- 与 say 组合而来，指否认、反驳或挑战某项说法，也有较少见的名词用法表示否认。',C('gainsay.s2','专家意见','Few residents could gainsay the engineer’s warning after the inspection revealed deep cracks in every support pillar.','检查发现每根支撑柱都有深裂缝后，几乎没有居民能够反驳工程师的警告。','Few residents could gainsay the engineer’s warning / after the inspection revealed deep cracks / in every support pillar.','gainsay + 观点或权威意见表示质疑、反驳；after 引出证据。','有明确检查证据支持工程师意见，使其难以被驳斥，符合 s2。'),M('No one could gainsay the claim because everyone openly denied and contradicted it.','No one could gainsay the claim because everyone accepted it as well supported.','所有人都否认该说法，与“无人能够反驳”矛盾。'),[Q('gainsay',1,1,'To gainsay a statement is to?','deny or contradict it','repeat it word for word','write it in a notebook','gainsay 作动词意为否认或反驳。'),Q('gainsay',2,2,'A scientist may gainsay an authority by?','challenging the claim with contrary evidence','agreeing before reading the evidence','copying the claim without comment','用相反证据挑战权威说法体现 s2。'),Q('gainsay',3,3,'In the phrase “there is no gainsaying the result,” gainsaying means?','denying or contradicting it','celebrating it publicly','measuring it twice','gainsay 可作名词性用法，意为否认、反驳。'),Q('gainsay',4,1,'Which is closest to gainsay?','contradict','endorse','decorate','contradict 表示反驳、否认。')]);
P('gait','gait 可能源于古法语 gait“步态、举止”，可指行走或奔跑的方式，也可作动词指训练马匹采用特定步法。',C('gait.s1','运动医学','The therapist watched the patient’s gait from the front and side, noting that the left foot turned inward during each step.','治疗师从正面和侧面观察患者的步态，注意到他每走一步左脚都会内转。','The therapist watched the patient’s gait from the front and side / noting that the left foot turned inward / during each step.','gait 作名词指走路方式；noting 引出步态的具体特征。','观察脚步方向来评估行走方式，体现 gait 的步态义。'),M('The clinician assessed her gait by measuring the color of her eyes.','The clinician assessed her gait by observing how she walked.','眼睛颜色不能说明行走方式。'),[Q('gait',1,1,'A person’s gait is the way the person?','walks or runs','speaks into a microphone','writes a signature','gait 指步态。'),Q('gait',2,2,'To gait a horse is to?','train it to move with a particular step pattern','feed it a special grain','measure its height with a ruler','动词 gait 指训练马匹采用特定步法。'),Q('gait',3,1,'A doctor notices an uneven gait when?','one leg moves differently during walking','the patient changes eye color','the patient forgets a phone number','走路时两腿动作不同体现步态异常。'),Q('gait',4,1,'Which instrument might record a runner’s gait?','a motion-capture camera','a kitchen thermometer','a parking meter','动作捕捉可记录跑步步态。')]);
P('gallant','gallant 经古法语 galant“殷勤、勇敢”进入英语，可指临危英勇、外观堂皇，也可指对女性殷勤有礼的旧式用法。',C('gallant.s1','救援报道','A gallant firefighter returned to the building to guide two trapped residents toward the exit despite the thick smoke.','一位英勇的消防员冒着浓烟返回建筑物，引导两名被困居民前往出口。','A gallant firefighter returned to the building / to guide two trapped residents toward the exit / despite the thick smoke.','gallant 修饰 firefighter，指面对危险时英勇；despite 引出危险条件。','冒险返回救人体现勇敢高尚的 s1。'),M('The gallant rescuer hid safely outside while refusing to help anyone in danger.','The cowardly rescuer hid safely outside while refusing to help anyone in danger.','躲避危险且拒绝救援与英勇相反。'),[Q('gallant',1,1,'A gallant act in a fire would be?','risking oneself to guide people to safety','locking the exits to protect furniture','leaving everyone without warning','冒险救人体现英勇。'),Q('gallant',2,2,'A gallant palace is described as?','grand and impressive in appearance','small, plain, and unfinished','hidden from view under the ground','gallant 也可形容堂皇壮丽。'),Q('gallant',3,3,'In an old-fashioned compliment, a gallant man might be?','polite and attentive toward a woman','rude to every guest','unwilling to speak to anyone','旧式用法指对女性殷勤有礼。'),Q('gallant',4,1,'Which word is closest to gallant in the bravery sense?','valiant','timid','careless','valiant 指英勇。')]);
P('gallantry','gallantry 由 gallant 加 -ry 构成，可指临危勇敢行为，也可指旧式语境中殷勤礼貌的举止。',C('gallantry.s1','历史记载','The medal citation praised the sailor’s gallantry in rescuing the crew after their vessel capsized during the storm.','勋章授词赞扬了这名水手的英勇：风暴中船只倾覆后，他救出了全体船员。','The medal citation praised the sailor’s gallantry / in rescuing the crew / after their vessel capsized during the storm.','gallantry 表示英勇行为；in rescuing 说明勇敢行为的具体内容。','在危险风暴中救人属于英勇行为。'),M('The report praised his gallantry because he abandoned the crew and refused to enter the water.','The report criticized his cowardice because he abandoned the crew and refused to enter the water.','遗弃船员、不愿救援体现怯懦而非 gallantry。'),[Q('gallantry',1,1,'Gallantry in battle refers to?','brave and noble conduct','careful accounting of supplies','a type of ship’s kitchen','gallantry 可指战斗中的英勇行为。'),Q('gallantry',2,2,'Old accounts may use gallantry for?','polite, attentive behavior toward women','a method of measuring rainfall','a legal claim to farmland','gallantry 也有殷勤举止的旧义。'),Q('gallantry',3,1,'A rescue medal recognizes gallantry when someone?','acts courageously to save others','avoids every possible duty','wins a cooking contest','英勇救人体现 gallantry。'),Q('gallantry',4,1,'The closest opposite of gallantry in danger is?','cowardice','valor','heroism','cowardice 与英勇相反。')]);
P('galley','galley 经古法语源自希腊语与拉丁语中对桨帆船的称呼；现代也指船只或飞机上的厨房。',C('galley.s2','航空服务','The flight attendant collected meal trays in the aircraft galley, a narrow kitchen area behind the passenger cabin.','乘务员在飞机厨房收集餐盘；那是一处位于客舱后方的狭窄备餐区域。','The flight attendant collected meal trays / in the aircraft galley / a narrow kitchen area / behind the passenger cabin.','aircraft galley 指机上厨房；同位语解释其空间位置与功能。','机组人员在飞机内的备餐区工作，体现 s2。'),M('The aircraft galley was the passenger seat where travelers fastened their belts.','The aircraft cabin contained the passenger seats where travelers fastened their belts.','乘客座位位于客舱，不是厨房 galley。'),[Q('galley',1,1,'An ancient galley was mainly powered by?','oars, sometimes with sails','a steam turbine and jet engine','a group of railway wheels','古代 galley 是以桨为主的船。'),Q('galley',2,2,'An aircraft galley is?','the kitchen area where meals are prepared or stored','the cockpit where pilots steer','the luggage compartment under the seats','飞机 galley 是厨房或备餐区。'),Q('galley',3,1,'Which worker is most likely in a ship’s galley?','a cook preparing meals','a diver measuring seabed depth','a navigator repairing a mast','船上厨房由厨师准备食物。'),Q('galley',4,1,'The word galley can refer to?','either an oared ship or a vessel’s kitchen','only a modern passenger seat','a type of land-based bicycle','两项词义分别为桨船和船机厨房。')]);
P('gallium','gallium 以拉丁语 Gallia（高卢，即法国）命名，是镓元素；它用于半导体等材料，也因熔点低而用于某些温度计。',C('gallium.s1','材料科学','The engineer selected gallium compounds for a semiconductor component because their electrical properties suited the device’s operating range.','工程师为半导体元件选择镓化合物，因为其电学性质适合该设备的工作范围。','The engineer selected gallium compounds for a semiconductor component / because their electrical properties / suited the device’s operating range.','gallium 是化学元素名；compounds 表示其化合物用于元件。','镓及其化合物用于半导体材料，符合词义。'),M('Gallium is a species of bird that dives into the sea to catch fish.','A gannet is a species of bird that dives into the sea to catch fish.','镓是金属元素；海鸟是 gannet。'),[Q('gallium',1,1,'Gallium is?','a metallic chemical element','a large seabird','a style of medieval poetry','gallium 是金属元素镓。'),Q('gallium',2,1,'Gallium compounds are useful in some?','semiconductor devices','wooden sailing oars','paper newspapers','镓化合物可用于半导体。'),Q('gallium',3,1,'Which symbol represents gallium on the periodic table?','Ga','Gm','Gl','镓的元素符号为 Ga。'),Q('gallium',4,1,'Gallium differs from a gannet because gallium is?','a chemical element, not a bird','a bird that catches fish','a type of oared ship','gallium 是元素，gannet 才是鸟。')]);
P('gallop','gallop 经古法语 galoper 进入英语，可作名词指马的最快步态，也可作动词表示马或人快速奔跑，及物用法可使马飞跑。',C('gallop.s2','马术训练','When the gate opened, the horse galloped across the paddock while the rider kept a balanced seat and followed the instructor’s signal.','闸门打开后，马在围场里飞奔，骑手保持平衡坐姿并听从教练的信号。','When the gate opened / the horse galloped across the paddock / while the rider kept a balanced seat / and followed the instructor’s signal.','gallop 作不及物动词，主语 horse 自行疾驰；while 引出骑手的同步动作。','马快速奔跑，符合 gallop 的 s2。'),M('The horse galloped at a slow walk, never lifting its feet from the ground.','The horse walked slowly, never lifting its feet from the ground.','缓慢步行与疾驰不相符。'),[Q('gallop',1,1,'A horse’s gallop is?','its very fast running gait','its slowest standing posture','a kitchen used on a ship','gallop 名词指马的快速步态。'),Q('gallop',2,2,'If a horse gallops across a field, it?','runs very fast','stands still beside a fence','eats quietly from a trough','动词不及物义表示飞奔。'),Q('gallop',3,3,'To gallop a horse means to?','make it run fast','teach it to remain motionless','measure its height','及物用法是使马快速奔跑。'),Q('gallop',4,1,'Which scene shows a gallop?','a horse races at full speed toward the finish','a horse pauses to drink','a horse is brushed in its stall','全速奔向终点体现 gallop。')]);
P('galvanization','galvanization 是 galvanize 加 -ation 构成的名词，可指给铁或钢镀锌防锈，也可比喻人群突然受到激励而行动。',C('galvanization.s1','金属防护','The galvanization of the steel fence added a zinc coating that slowed rusting in the coastal air.','对钢围栏进行镀锌后，表面的锌层减缓了它在海边空气中的锈蚀。','The galvanization of the steel fence / added a zinc coating / that slowed rusting / in the coastal air.','galvanization of steel 指钢材镀锌；that 从句说明防锈效果。','在钢表面覆盖锌层防锈，符合工艺义 s1。'),M('The galvanization removed the zinc layer and made the steel rust faster.','The corrosion damaged the steel after its protective zinc layer was removed.','镀锌是添加防护层，不是去除锌层。'),[Q('galvanization',1,1,'Galvanization of steel usually means?','coating it with zinc to resist rust','covering it with sugar to improve taste','heating it until it becomes wood','金属镀锌可防止锈蚀。'),Q('galvanization',2,2,'The galvanization of a community is a sudden?','rousing that gets people to act','chemical coating of every building','period of complete inactivity','比喻义指激励人群采取行动。'),Q('galvanization',3,1,'Which object may undergo galvanization?','an iron gate that needs rust protection','a loaf of bread before baking','a book title printed on paper','铁门可镀锌防锈。'),Q('galvanization',4,1,'A campaign’s galvanization of volunteers results in?','people becoming motivated to participate','the volunteers being coated in metal','the campaign ending before anyone acts','激励会促使志愿者行动。')]);
P('galvanize','galvanize 以 Luigi Galvani 姓氏命名，原指用电刺激肌肉，后指激励人们迅速行动，也指给铁或钢镀锌。',C('galvanize.s1','社区行动','The sudden rise in local asthma cases galvanized residents to demand cleaner air and press the council to monitor traffic pollution.','当地哮喘病例突然增加，激励居民要求改善空气质量，并敦促市议会监测交通污染。','The sudden rise in local asthma cases / galvanized residents / to demand cleaner air / and press the council to monitor traffic pollution.','galvanize + 人 + to do 表示激励某人采取行动；to 后并列两个行动。','病例增加促使居民立即组织倡议，符合激励义 s1。'),M('The news galvanized residents by persuading everyone to remain passive and take no action.','The news discouraged residents by persuading everyone to remain passive and take no action.','劝人消极不行动是 discouraging，而非 galvanizing。'),[Q('galvanize',1,1,'A speech galvanizes a team when it?','inspires the team to act energetically','coats the team’s equipment with zinc','makes every member fall asleep','galvanize 可表示激励采取行动。'),Q('galvanize',2,2,'To galvanize an iron railing is to?','cover it with zinc for protection','remove all paint and rust with a cloth','make it produce a speech','galvanize 也有给铁镀锌的技术义。'),Q('galvanize',3,1,'Which event might galvanize a neighborhood?','a serious flood prompts residents to organize a safety plan','a quiet afternoon passes without incident','a notice is filed and nobody reads it','危机促使居民组织应对，体现激励义。'),Q('galvanize',4,1,'Choose the common grammar pattern.','galvanize people into taking action','galvanize people at to take action','galvanize people by action into','常见结构 galvanize somebody into doing。')]);
P('gambit','gambit 来自意大利语 gambetto“绊脚”，经棋类术语发展，指开局有意弃子换取位置的棋法，也泛指策略性第一步。',C('gambit.s1','谈判策略','The negotiator’s opening gambit was to offer a longer contract in exchange for a lower price, setting the terms for later discussion.','谈判代表的开场策略是以延长合同期限换取较低价格，为后续讨论设定条件。','The negotiator’s opening gambit was to offer a longer contract / in exchange for a lower price / setting the terms / for later discussion.','opening gambit 指谈判开局的策略性行动；in exchange for 表示交换条件。','首个提议用于争取后续谈判优势，符合 gambit 的泛化义。'),M('Her opening gambit was an accidental remark that had no strategic purpose or effect.','Her opening remark was an accidental comment that had no strategic purpose or effect.','没有策略目的的偶然言语不是 gambit。'),[Q('gambit',1,1,'In chess, a gambit usually involves?','sacrificing material early for positional advantage','resigning before making a move','moving every piece off the board','棋类 gambit 以弃子换取位置优势。'),Q('gambit',2,1,'In negotiation, an opening gambit is?','a strategic first move','the final signed agreement','an unrelated lunch break','泛指开局策略或第一步。'),Q('gambit',3,1,'A politician’s gambit might be?','a deliberate first proposal designed to shape debate','an accidental cough during a speech','a list of yesterday’s weather readings','有意提出、塑造讨论方向属于策略性举动。'),Q('gambit',4,1,'Which is closest to gambit in a business meeting?','opening tactic','final invoice','quiet apology after the meeting','gambit 可表示开场策略。')]);
P('gambol','gambol 经法语 gambade“雀跃、跳跃”进入英语，指轻快嬉戏地跳跃或蹦跳。',C('gambol.s1','动物行为','The lambs gambolled across the meadow after the gate opened, circling one another before settling beside their mothers.','羊羔们在栅门打开后在草地上欢快蹦跳，彼此追逐一会儿，随后才回到母羊身边。','The lambs gambolled across the meadow / after the gate opened / circling one another / before settling beside their mothers.','gambol 可作动词表示嬉戏跳跃；-ed 拼写有双 l。','羊羔轻快跳跃、互相追逐，符合 gambol 的玩耍义。'),M('The lambs gambolled by lying motionless in separate stalls and refusing to move.','The lambs rested by lying motionless in separate stalls and refusing to move.','静止不动与雀跃嬉戏相反。'),[Q('gambol',1,1,'To gambol is to?','skip or leap playfully','stand at attention without moving','measure a field with a chain','gambol 表示轻快嬉戏地跳跃。'),Q('gambol',2,1,'Which scene shows gambolling?','young goats springing around each other in a field','a tortoise remaining still under a log','a farmer weighing grain in a barn','小羊羔互相蹦跳体现 gambol。'),Q('gambol',3,1,'Children gambolled on the lawn means they?','played by leaping about','worked quietly at a desk','argued over a contract','gambol 表示嬉戏、雀跃。'),Q('gambol',4,1,'The closest contrast to gambol is?','sit motionless','leap playfully','skip about','静止不动与跳跃嬉戏相反。')]);

P('gamma','gamma 取自希腊字母 γάμμα 的转写，是希腊字母表第三个字母，通常写作大写 Γ、小写 γ。',C('gamma.s1','科学符号','The physicist used the symbol gamma for the third radiation type in the diagram, writing the lowercase Greek letter γ beside the detector reading.','物理学家在示意图中用 gamma 表示第三种辐射，并在探测器读数旁写下小写希腊字母 γ。','The physicist used the symbol gamma / for the third radiation type in the diagram / writing the lowercase Greek letter γ / beside the detector reading.','gamma 是希腊字母名称；此处说明其符号在图表中的用法。','γ 是希腊字母 gamma 的小写形式。'),M('Gamma is the first letter of the Greek alphabet and is written only as alpha.','Alpha is the first letter of the Greek alphabet; gamma is the third and is written γ or Γ.','gamma 是第三个希腊字母，不是第一个 alpha。'),[Q('gamma',1,1,'Gamma is which Greek letter in sequence?','the third','the first','the twenty-fourth','gamma 是希腊字母表第三个字母。'),Q('gamma',2,1,'Which symbol is lowercase gamma?','γ','β','δ','小写 gamma 写作 γ。'),Q('gamma',3,1,'In a Greek alphabet list, gamma follows?','alpha and beta','omega and psi','delta and epsilon','alpha、beta 之后是 gamma。'),Q('gamma',4,1,'A scientist labels a detector with γ. The symbol names?','gamma','zeta','lambda','γ 是 gamma 的符号。')]);
P('gangster','gangster 由 gang（犯罪团伙）加 -ster 构成，指暴力犯罪团伙成员，也可贬义泛指以暴力或恐吓欺压他人的恶棍。',C('gangster.s1','犯罪报道','Police arrested the gangster after investigators linked him to a group that extorted shopkeepers and used threats to collect illegal payments.','调查人员将他与勒索店主、以威胁手段收取非法款项的团伙联系起来后，警方逮捕了这名黑帮分子。','Police arrested the gangster / after investigators linked him to a group / that extorted shopkeepers / and used threats to collect illegal payments.','gangster 指犯罪团伙成员；that 从句描述团伙的暴力勒索活动。','团伙成员参与有组织的勒索犯罪，符合 s1。'),M('The gangster was a harmless librarian who never belonged to a criminal group or threatened anyone.','The librarian was a harmless worker who never belonged to a criminal group or threatened anyone.','无犯罪团伙联系且不威胁他人的图书管理员不是 gangster。'),[Q('gangster',1,1,'A gangster is typically?','a member of a violent criminal group','a scientist who studies galaxies','a person who grows garden plants','gangster 指暴力犯罪团伙成员。'),Q('gangster',2,2,'Calling a bully a gangster may mean the bully?','uses threats and force to dominate others','runs a lawful reading club','teaches a history class','泛指用暴力恐吓欺压者，对应 s2。'),Q('gangster',3,1,'Which action fits a gangster in a crime report?','extorting money from local businesses','organizing a legal charity auction','publishing a weather forecast','勒索商家是典型犯罪团伙活动。'),Q('gangster',4,1,'A gangster differs from a gang member in a lawful sports club because the gangster?','is involved in violent crime','wears the same team color','meets other people regularly','犯罪和暴力性质使其不同于合法社团成员。')]);
P('gannet','gannet 来自古英语与北欧语系中对该海鸟的称呼，指长喙的大型海鸟，常俯冲入海捕捉鱼类。',C('gannet.s1','海鸟观察','A gannet folded its wings and plunged toward the sea, striking the water headfirst before resurfacing with a fish.','一只塘鹅收拢翅膀俯冲向海，头朝下扎入水中，随后浮出水面，嘴里衔着一条鱼。','A gannet folded its wings and plunged toward the sea / striking the water headfirst / before resurfacing with a fish.','gannet 作鸟名；plunge toward 与 resurfacing 描述俯冲捕鱼动作。','塘鹅以俯冲入海捕鱼为特征。'),M('The gannet was a land mammal that grazed on grass and never entered the water.','The gazelle was a land mammal that grazed on grass and rarely entered the water.','gannet 是海鸟；草食陆生羚羊是 gazelle。'),[Q('gannet',1,1,'A gannet is a?','large seabird that dives for fish','small antelope that runs across grassland','metal used in semiconductor chips','gannet 是俯冲捕鱼的海鸟。'),Q('gannet',2,1,'How does a gannet often catch fish?','by plunging into the sea','by digging tunnels under a field','by grazing on leaves','塘鹅常俯冲入海捕食。'),Q('gannet',3,1,'Which feature fits a gannet?','a long bill and a coastal habitat','a woolly coat and mountain horns','a metallic body and electrical charge','长喙和海岸栖息地符合塘鹅。'),Q('gannet',4,1,'A gannet is most likely spotted?','over the sea near a fishing colony','inside a chemistry laboratory','in a city courtroom','塘鹅常在海上或海鸟栖息地出现。')]);
P('garb','garb 可能经古法语 garbe“装束、外表”进入英语，可指特定样式的衣服，也可比喻事物呈现的外观或伪装。',C('garb.s2','外观与真实','The old warehouse appeared in the garb of a modern gallery after new lights and white walls concealed its industrial interior.','添装新灯和白墙后，旧仓库披上现代画廊的外表，遮住了原有的工业内部结构。','The old warehouse appeared in the garb of a modern gallery / after new lights and white walls / concealed its industrial interior.','in the garb of 是比喻搭配，表示呈现某种外观；after 引出变化方式。','旧仓库只是看起来像画廊，实际用途被外表掩盖，符合 s2。'),M('The monk wore formal court garb while dressed only in ordinary hiking boots and a raincoat.','The monk wore practical hiking garb, including sturdy boots and a raincoat.','登山靴和雨衣是户外装束，不是正式宫廷服饰。'),[Q('garb',1,1,'A judge’s garb refers to the judge’s?','clothing or distinctive dress','legal opinion about a case','method for measuring a courtroom','garb 可指某种样式的服装。'),Q('garb',2,2,'A company may appear in the garb of a charity when it?','uses a charitable image to hide its commercial purpose','displays its registered accounts openly','donates funds with no advertising','garb 的比喻义可指遮掩真实目的的外表。'),Q('garb',3,1,'Which phrase uses garb literally?','the actor wore royal garb on stage','the building appeared in the garb of a fortress','the argument took the garb of a rumor','演员穿上王室服饰是字面义。'),Q('garb',4,1,'In “winter garb,” garb means?','clothing suitable for the season','a kind of sea bird','a financial guarantee','winter garb 指冬季衣着。')]);
P('gardening','gardening 由 garden 加 -ing 构成，指种植、照料花园或菜园的活动。',C('gardening.s1','社区园艺','Every Saturday, the neighbors take turns gardening in the shared courtyard, pruning the herbs and watering seedlings before the heat of the day.','邻居们每周六轮流在共用庭院里做园艺，趁天气还不热时修剪香草并给幼苗浇水。','Every Saturday / the neighbors take turns gardening in the shared courtyard / pruning the herbs / and watering seedlings before the heat of the day.','take turns gardening 表示轮流园艺；pruning 和 watering 列出具体活动。','修剪植物并培育幼苗属于园艺工作。'),M('The gardening club maintained its plot by paving every bed and removing all plants and soil.','The construction crew paved the plot and removed its plants and soil.','铺地并清除植物土壤是施工，不是种植照料花园。'),[Q('gardening',1,1,'Gardening involves?','cultivating and caring for plants in a garden','repairing a ship’s kitchen','studying only family history','gardening 指园艺活动。'),Q('gardening',2,1,'Which task is gardening?','pruning a rose bush and planting bulbs','checking a court’s legal filings','measuring the speed of a train','修剪花木与种植球根属于园艺。'),Q('gardening',3,1,'Someone who enjoys gardening may keep?','a vegetable patch or flower beds','a collection of court verdicts only','a ship powered by oars','种植蔬菜或花卉是常见园艺。'),Q('gardening',4,1,'The closest broad activity to gardening is?','horticulture','genealogy','geometry','horticulture 是园艺学或园艺活动。')]);
P('gargantuan','gargantuan 以 François Rabelais 小说中的巨人 Gargantua 命名，形容体积或数量异常庞大。',C('gargantuan.s1','大型基础设施','The city faced a gargantuan repair bill after the storm damaged bridges, power lines, and water mains across the entire region.','风暴损坏了整个地区的桥梁、电线和供水主管道后，市政府面临一笔巨额维修账单。','The city faced a gargantuan repair bill / after the storm damaged bridges, power lines, and water mains / across the entire region.','gargantuan 修饰 bill，表示金额规模巨大；after 引出费用产生的原因。','受损设施遍及整个地区，导致异常庞大的维修费用。'),M('The gargantuan fee was one cent, so small that it could not cover even a stamp.','The tiny fee was one cent, so small that it could not cover even a stamp.','一分钱极其微小，不能称为 gargantuan。'),[Q('gargantuan',1,1,'A gargantuan building is?','extraordinarily large','too small to enter','made only of paper','gargantuan 表示异常巨大。'),Q('gargantuan',2,1,'Which amount is gargantuan?','a repair bill of several billion dollars','a one-cent fee','a single grain of rice','数十亿美元账单属于巨额。'),Q('gargantuan',3,1,'The word gargantuan alludes to?','a giant character in a Rabelais story','a Greek letter used in equations','a small bird that dives for fish','词源来自小说中的巨人 Gargantua。'),Q('gargantuan',4,1,'Choose the closest synonym for gargantuan.','enormous','minute','ordinary','enormous 表示巨大。')]);
P('garland','garland 经古法语与日耳曼语词源进入英语，通常指用花或叶编成的环状装饰，也可作动词表示给人或场所戴上、装点花环。',C('garland.s2','庆祝仪式','After the race, volunteers garlanded the winners with fresh flowers and led them to the stage for the medal ceremony.','比赛结束后，志愿者给获胜者戴上鲜花花环，并领他们上台参加颁奖仪式。','After the race / volunteers garlanded the winners with fresh flowers / and led them to the stage / for the medal ceremony.','garland 作动词，garland someone with flowers 表示给某人戴花环。','志愿者把鲜花戴在获胜者身上，符合动词义 s2。'),M('The hosts garlanded the winners by removing every flower and leaving them undecorated.','The hosts left the winners undecorated by removing every flower.','移除花朵与装饰相反，不是 garland。'),[Q('garland',1,2,'To garland a winner is to?','decorate the winner with a wreath of flowers','hand the winner a measuring gauge','ask the winner to leave the stage','动词 garland 表示给人戴花环或装饰。'),Q('garland',2,1,'A garland is commonly made from?','flowers or leaves arranged in a wreath','metal screws packed in a box','a list of family names','花或叶编成的环状物是 garland。'),Q('garland',3,1,'Where might a garland be hung?','across a doorway for a festival','inside a sealed water pipe','under a courtroom bench as a document','节庆时可把花环挂在门口。'),Q('garland',4,2,'Which sentence uses garland as a verb?','They garlanded the statue with greenery.','A garland of leaves hung above the door.','She bought a flower garland.','garlanded 是动词形式。')]);
P('garner','garner 源于古法语与日耳曼语中“谷仓、贮存”的词，现代动词表示逐渐收集或获得支持、信息等，名词旧义指谷仓。',C('garner.s1','公众支持','The proposal garnered support from neighborhood groups after its revised route avoided the school and added a safe crossing.','修订路线避开学校并增加安全过街设施后，该提案获得了社区团体的支持。','The proposal garnered support from neighborhood groups / after its revised route avoided the school / and added a safe crossing.','garner support 表示获得支持；after 从句说明支持增加的原因。','团体支持被逐步获得，符合动词 s1。'),M('The proposal garnered opposition by receiving unanimous approval from every neighborhood group.','The proposal garnered support by receiving unanimous approval from every neighborhood group.','一致赞成属于获得支持，而不是获得反对。'),[Q('garner',1,1,'To garner support is to?','gain or collect support','deny that support exists','store supporters inside a barn','garner 表示获得、汇集。'),Q('garner',2,2,'In its older noun sense, a garner is?','a building where grain is stored','a type of fencing sport','a device that measures blood pressure','名词旧义指谷仓。'),Q('garner',3,1,'A researcher may garner evidence by?','collecting records from several reliable sources','discarding every document','guessing without checking','从可靠来源收集材料属于 garner。'),Q('garner',4,1,'Which phrase is natural?','garner praise for the design','garner the design at from','garnering praise into to','常见搭配 garner praise/support。')]);
P('garnish','garnish 经古法语 garnir“装备、装饰”而来，可指用少量食材装饰菜肴，也可泛指点缀物或装饰行为。',C('garnish.s3','餐桌服务','The server placed a lemon twist beside the fish as a garnish, adding color and a fresh citrus aroma without covering the main dish.','服务员把一条柠檬皮放在鱼旁作配菜装饰，增添颜色和清新柑橘香，又没有盖住主菜。','The server placed a lemon twist beside the fish as a garnish / adding color and a fresh citrus aroma / without covering the main dish.','garnish 作名词指少量装饰食物的配料；as a garnish 标明用途。','柠檬皮作为配菜点缀，属于 s3。'),M('The chef used a garnish as the entire main course and served no substantial food.','The chef used a lemon twist as a garnish beside the main course.','garnish 通常是少量点缀或配菜，不是整份主菜。'),[Q('garnish',1,1,'To garnish a soup is to?','decorate it with a small attractive topping','remove every ingredient from it','measure its temperature with a gage','动词 garnish 表示给食物加装饰。'),Q('garnish',2,2,'A room may be garnished with paintings by being?','decorated with them','emptied of all decoration','measured from floor to ceiling','garnish 可泛指装饰、点缀。'),Q('garnish',3,3,'A parsley sprig served on a plate is a?','garnish','garrison','gambit','名词 garnish 可指菜肴上的装饰配菜。'),Q('garnish',4,1,'Which item is most likely a garnish?','a small sprig of herbs on a finished dish','a large sack of uncooked potatoes','a metal cooking range','少量香草常用于点缀成菜。')]);
P('garret','garret 经古法语与古诺尔曼法语词源发展，指阁楼顶层狭窄、简陋的房间，传统文学常描写贫穷作家或艺术家居住其中。',C('garret.s1','文学场景','The young poet wrote by candlelight in a cramped garret beneath the roof, storing manuscripts in a trunk beside the narrow bed.','年轻诗人在屋顶下狭窄的阁楼小间里借烛光写作，把手稿放在窄床旁的箱子中。','The young poet wrote by candlelight / in a cramped garret beneath the roof / storing manuscripts in a trunk / beside the narrow bed.','garret 指屋顶下简陋小房；beneath the roof 和 cramped 描写其位置、狭窄。','位于阁楼且狭小简陋的居室符合 garret。'),M('The family held a dance in the spacious ground-floor ballroom and called it a garret.','The family held a dance in the spacious ground-floor ballroom.','宽敞的底层舞厅不属于阁楼小间。'),[Q('garret',1,1,'A garret is usually?','a small room in the attic','a large underground swimming pool','a kitchen on an airplane','garret 指顶层阁楼中的小房间。'),Q('garret',2,1,'A novelist in a garret is likely living?','in a cramped space under the roof','in a ship’s rowing compartment','inside a garden shed made of glass','阁楼小间常位于屋顶下且空间狭小。'),Q('garret',3,1,'Which phrase best fits garret?','a poorly furnished attic room','a grand palace dining hall','a field used to grow grain','简陋阁楼房间是 garret。'),Q('garret',4,1,'A garret differs from a cellar because it is?','near the roof rather than underground','always beneath the basement','a type of seabird','garret 在阁楼顶层，cellar 在地下。')]);
P('garrison','garrison 经古法语来自意为“防守、保护”的词，可作名词指驻守某地的军队，也可作动词表示派兵驻防。',C('garrison.s2','军事部署','The army garrisoned the mountain pass with a small unit so that supply trucks could cross safely during the winter.','军方派一支小部队驻守山口，以便冬季补给卡车安全通行。','The army garrisoned the mountain pass with a small unit / so that supply trucks could cross safely / during the winter.','garrison + 地点表示派兵驻守；with a unit 指驻守部队。','军队把人员部署在山口防守，符合动词义 s2。'),M('The army garrisoned the pass by withdrawing every soldier and leaving the route undefended.','The army abandoned the pass by withdrawing every soldier and leaving the route undefended.','撤兵并使地点无人防守是放弃驻守，不是 garrison。'),[Q('garrison',1,1,'A garrison is?','a body of soldiers stationed to defend a place','a kitchen aboard an aircraft','a group of genealogists','garrison 名词指驻军。'),Q('garrison',2,2,'To garrison a fort means to?','station soldiers there for defense','remove every soldier from it','decorate it with a flower wreath','动词 garrison 表示派兵驻守。'),Q('garrison',3,1,'A border town may need a garrison when?','soldiers are posted there to defend the area','it is converted into a greenhouse','its residents stop using roads','驻军负责防守边境地区。'),Q('garrison',4,1,'Which sentence uses garrison as a noun?','The garrison guarded the bridge overnight.','They garrisoned the bridge with troops.','The bridge was garrisoned before dawn.','主语指一支军队时 garrison 作名词。')]);
P('garrulity','garrulity 源自拉丁语 garrulus“喋喋不休的”，加 -ity 构成名词，指过度健谈、絮叨的特质。',C('garrulity.s1','会议观察','The chair appreciated the researcher’s ideas but struggled to keep the meeting on schedule because of his garrulity and long digressions.','主席认可研究员的想法，但因他过度健谈、不断长篇岔题，难以让会议按时结束。','The chair appreciated the researcher’s ideas / but struggled to keep the meeting on schedule / because of his garrulity and long digressions.','garrulity 是特质名词；because of 后指出话多及跑题造成的影响。','长篇闲谈阻碍会议进程，体现过度健谈。'),M('Her garrulity meant she answered every question in one word and never added a detail.','Her brevity meant she answered every question in one word and never added a detail.','只用一词回答体现简短，不是喋喋不休。'),[Q('garrulity',1,1,'Garrulity is the quality of being?','excessively talkative','unable to hear speech','skilled at repairing ships','garrulity 指过度健谈。'),Q('garrulity',2,1,'A meeting is delayed by a speaker’s garrulity when the speaker?','keeps talking at length and strays from the topic','answers briefly and yields the floor','arrives after the meeting ends','长篇说话并不断岔题体现 garrulity。'),Q('garrulity',3,1,'Which trait contrasts with garrulity?','taciturnity','loquacity','verbosity','taciturnity 指沉默寡言。'),Q('garrulity',4,1,'The chair asked for brevity because of the panelist’s?','garrulity','gait','gallantry','garrulity 是冗长多话。')]);
P('garrulous','garrulous 来自拉丁语 garrulus“喋喋不休的”，形容说话过多、冗长的人或谈话。',C('garrulous.s1','访谈现场','The garrulous witness answered a simple question with a ten-minute story about unrelated events, so the lawyer asked her to focus on the date.','健谈过头的证人用一段十分钟、与问题无关的故事回答简单提问，律师只好请她聚焦日期。','The garrulous witness answered a simple question / with a ten-minute story about unrelated events / so the lawyer asked her / to focus on the date.','garrulous 修饰 witness，表示过度爱说；so 引出沟通困难的结果。','回答冗长且离题说明证人过度健谈。'),M('The garrulous speaker remained silent throughout the interview and refused to answer.','The taciturn speaker remained silent throughout the interview and refused to answer.','全程沉默与 garrulous（话多）相反。'),[Q('garrulous',1,1,'A garrulous neighbor is likely to?','talk at length, often more than necessary','avoid speaking to anyone','measure every conversation with a clock','garrulous 指话多、健谈过头。'),Q('garrulous',2,1,'Which reply sounds garrulous?','a long digression after a simple yes-or-no question','a brief “yes” followed by silence','a written answer with one exact date','简单问题引出长篇离题回答体现 garrulous。'),Q('garrulous',3,1,'Choose the closest synonym for garrulous.','talkative','reticent','silent','talkative 表示健谈。'),Q('garrulous',4,1,'A garrulous guest may be asked to?','let others speak and keep the story shorter','stop listening to all other guests','measure the room’s temperature','话太多的客人可能需让别人发言并简短些。')]);
P('gaseous','gaseous 由 gas 加 -eous 构成，描述气体状态或与气体有关的物质。',C('gaseous.s1','物质状态','At room temperature, the sample remained gaseous and expanded to fill the sealed container rather than keeping a fixed shape.','在室温下，样品保持气态并膨胀至充满密封容器，而不像固体那样保持固定形状。','At room temperature / the sample remained gaseous / and expanded to fill the sealed container / rather than keeping a fixed shape.','gaseous 作表语形容物质状态；rather than 对照气体和固定形状。','样品呈气体并填满容器，符合气态义。'),M('The gaseous sample kept a rigid shape and could be lifted as one solid block.','The solid sample kept a rigid shape and could be lifted as one block.','保持固定形状并能成块取出是固态特征，不是 gaseous。'),[Q('gaseous',1,1,'A gaseous substance exists as?','a gas','a rigid solid','a liquid with a fixed volume only','gaseous 指气体状态。'),Q('gaseous',2,1,'Which property is typical of gaseous matter?','it spreads to fill its container','it always keeps a fixed shape','it cannot move between particles','气体会扩散并占满容器空间。'),Q('gaseous',3,1,'A gaseous cloud around a star consists mainly of?','matter in gas form','solid wooden blocks','liquid ink on paper','gas form 的物质为 gaseous。'),Q('gaseous',4,1,'The closest contrast to gaseous is?','solid','vaporous','gas-like','solid 与气态相对。')]);
P('gaslit','gaslit 是 gaslight 的过去分词形容词，指由煤气灯照明的；此处按词典所列字面义使用。',C('gaslit.s1','历史建筑','The restored theatre was gaslit with replicas of nineteenth-century lamps, giving visitors an idea of how the stage once looked before electric lighting.','修复后的剧院用仿制的十九世纪煤气灯照明，让访客了解电灯出现前舞台的样子。','The restored theatre was gaslit with replicas of nineteenth-century lamps / giving visitors an idea / of how the stage once looked / before electric lighting.','gaslit 修饰 theatre，表示以煤气灯照明；before 对照电气照明出现之前。','仿制煤气灯照亮剧院，符合词典所列照明义。'),M('The gaslit hall was illuminated only by modern LED panels and contained no gas lamps.','The electrically lit hall was illuminated only by modern LED panels and contained no gas lamps.','完全由 LED 照明、不用煤气灯的大厅不是字面义 gaslit。'),[Q('gaslit',1,1,'A gaslit room is illuminated by?','gas lamps','solar panels only','candles made of ice','gaslit 指由煤气灯照亮。'),Q('gaslit',2,1,'A museum recreates a gaslit street to show?','how gas lamps once lit public spaces','how electric screens display maps','how daylight enters a cave','复原煤气灯街景展示旧式照明。'),Q('gaslit',3,1,'Which scene is gaslit?','a corridor lit by working gas fixtures','a corridor lit only by battery LEDs','a corridor with no light at all','工作中的煤气灯照明符合该词义。'),Q('gaslit',4,1,'Gaslit differs from electrically lit because gaslit means?','lit by gas lamps','lit by electric bulbs','lit only by the sun','gaslit 的光源是煤气灯。')]);
P('gasolene','gasolene 是 gasoline 的一种旧式拼写变体，指从石油提炼、用于火花点火发动机的液体燃料；不把合法变体当作错误拼写。',C('gasolene.s1','车辆燃料','The manual calls the fuel gasolene, an older spelling for the petroleum liquid used in the small spark-ignition engine.','说明书把燃料写作 gasolene，这是 gasoline 的一种旧式拼法，指小型火花点火发动机使用的石油液体燃料。','The manual calls the fuel gasolene / an older spelling for the petroleum liquid / used in the small spark-ignition engine.','gasolene 指汽油；此处说明它与 gasoline 是拼写变体，不表示另一种燃料。','该液体燃料用于火花点火发动机，符合词义。'),M('The manual used gasolene as the name for water supplied to the engine’s cooling system.','The manual used coolant as the name for water supplied to the engine’s cooling system.','冷却液用于发动机冷却；gasolene 是供发动机燃烧的燃料。'),[Q('gasolene',1,1,'Gasolene is a liquid fuel refined from?','petroleum','freshwater algae only','iron ore','gasolene 指石油提炼的汽油。'),Q('gasolene',2,1,'A small spark-ignition engine may burn?','gasolene','drinking water','dry sand','此类发动机以汽油为燃料。'),Q('gasolene',3,1,'Gasolene is an accepted spelling variant of?','gasoline','garrison','gallium','gasolene 与 gasoline 是拼写变体。'),Q('gasolene',4,1,'Which use fits gasolene?','fueling a petrol engine','filling a bird feeder','coating steel with zinc','汽油用于给发动机提供燃料。')]);
P('gatherer','gatherer 由 gather 加施事者后缀 -er 构成，可指采集食物的人，也可指收集信息、物品或其他资源的人。',C('gatherer.s1','田野研究','The field gatherer collected fallen seeds from marked plots, recording the plant species and location before placing each sample in a labeled envelope.','田野采集员从标记样地收集落下的种子，记录植物种类和地点后，把每份样本放入贴好标签的信封。','The field gatherer collected fallen seeds from marked plots / recording the plant species and location / before placing each sample in a labeled envelope.','gatherer 指执行收集工作的人；recording 与 placing 描述采集流程。','收集并记录种子样本，体现 gatherer 的采集义。'),M('The gatherer returned every sample to the ground and collected no food, data, or objects.','The observer returned every sample to the ground and collected no food, data, or objects.','没有收集任何物品的人不是 gatherer。'),[Q('gatherer',1,1,'A gatherer is someone who?','collects food, information, or objects','only measures the Earth’s magnetic field','teaches horse gaits','gatherer 指收集者或采集者。'),Q('gatherer',2,1,'An information gatherer might?','interview residents and record their answers','delete all survey responses','avoid asking any questions','收集访谈回答属于 gathering information。'),Q('gatherer',3,1,'In anthropology, a hunter-gatherer obtains food by?','hunting animals and collecting wild plants','growing grain in irrigated fields only','buying every meal from a restaurant','hunter-gatherer 靠狩猎与采集获取食物。'),Q('gatherer',4,1,'The closest verb to gatherer is?','collect','scatter','discard','gatherer 源自动词 gather。')]);
P('gauche','gauche 来自法语 gauche“左边的、笨拙的”，在英语中形容社交上笨拙不自在，也可指缺乏礼貌和得体。',C('gauche.s1','社交礼仪','His gauche attempt to congratulate the couple interrupted their private conversation, so he quickly apologized and waited for a better moment.','他笨拙地试图向这对新人道贺，却打断了他们的私下交谈，于是很快道歉并等待更合适的时机。','His gauche attempt to congratulate the couple / interrupted their private conversation / so he quickly apologized / and waited for a better moment.','gauche 修饰 attempt，表示社交上不够得体；so 引出其补救行为。','在不合时宜的时刻插话体现社交笨拙 s1。'),M('She made a gauche remark by carefully choosing a tactful compliment that everyone welcomed.','She made a tactful remark by carefully choosing a considerate compliment that everyone welcomed.','得体、体贴的赞美不是 gauche。'),[Q('gauche',1,1,'A gauche person may be?','awkward and unsure in social situations','confidently graceful at every gathering','highly skilled at measuring rocks','gauche 指社交笨拙、不自在。'),Q('gauche',2,2,'A gauche comment is one that?','lacks politeness or social grace','shows careful tact','contains a precise scientific measurement','s2 指粗鲁或不够得体。'),Q('gauche',3,1,'Which action is gauche at a formal dinner?','asking a stranger loudly about a painful private matter','waiting for the host to introduce guests','thanking the cook for the meal','当众追问陌生人的痛苦隐私很失礼。'),Q('gauche',4,1,'The closest opposite of gauche manners is?','tactful','awkward','clumsy','tactful 表示得体、圆融。')]);
P('gaunt','gaunt 来自北欧语系词源，形容因饥饿、疾病或受苦而瘦削憔悴，也可描述荒凉、空旷且令人不适的地方。',C('gaunt.s1','灾后救助','After weeks without reliable food, the gaunt survivors looked exhausted, and the aid workers arranged medical checks before moving them to shelter.','数周缺乏稳定食物后，幸存者瘦削憔悴、十分疲惫；救援人员先安排体检，再将他们转移到避难所。','After weeks without reliable food / the gaunt survivors looked exhausted / and the aid workers arranged medical checks / before moving them to shelter.','gaunt 修饰 survivors，表示因匮乏而瘦弱憔悴；after 从句说明成因。','长期缺粮导致消瘦和疲惫，符合 s1。'),M('The gaunt patient had gained healthy weight, looked vigorous, and showed no sign of hardship.','The healthy patient had gained weight, looked vigorous, and showed no sign of hardship.','体态健壮、没有受苦迹象与 gaunt 的憔悴义相反。'),[Q('gaunt',1,1,'A gaunt face often looks?','thin and drawn after hardship','round and well-fed','covered with colorful feathers','gaunt 常形容消瘦憔悴。'),Q('gaunt',2,2,'A gaunt landscape is?','bare, bleak, and without comfort','lush with flowers and trees','crowded with cheerful shops','gaunt 的地方义指荒凉、萧瑟。'),Q('gaunt',3,1,'Which person might be described as gaunt?','someone visibly weakened after a long illness','someone energetic after a restful holiday','someone wearing a formal uniform','长期疾病后明显消瘦的人符合词义。'),Q('gaunt',4,1,'The closest contrast to a gaunt wasteland is?','a lush, welcoming valley','a bare and grim plain','an empty, bleak field','茂盛宜人的山谷与荒凉之地相反。')]);
P('gazelle','gazelle 经法语源自阿拉伯语 ghazāl，指一种敏捷、奔跑迅速的小型羚羊；文学中也可比喻身姿轻盈的人。',C('gazelle.s1','野生动物','A gazelle sprang across the dry plain in a series of long leaps, escaping the approaching predator before it reached the herd.','一只瞪羚在干燥平原上连续大步跳跃，在捕食者靠近群体前逃脱。','A gazelle sprang across the dry plain / in a series of long leaps / escaping the approaching predator / before it reached the herd.','gazelle 是羚羊名；spring 和 leaps 表现其敏捷奔跑。','小型羚羊以敏捷跳跃逃避捕食者，符合 s1。'),M('The gazelle was a slow-moving seabird that caught fish by diving into the water.','The gannet was a seabird that caught fish by diving into the water.','gazelle 是陆生羚羊；俯冲捕鱼的海鸟是 gannet。'),[Q('gazelle',1,1,'A gazelle is a?','small, swift antelope','large seabird with a long bill','metal used in electronics','gazelle 指敏捷的羚羊。'),Q('gazelle',2,2,'In literary comparison, calling a dancer a gazelle suggests the dancer is?','graceful and swift','awkward and immobile','made of metal','比喻义突出动作轻盈敏捷。'),Q('gazelle',3,1,'Where would a wild gazelle most likely be seen?','running across open grassland','nesting on a sea cliff','living in an underground mine','瞪羚常在开阔地带活动。'),Q('gazelle',4,1,'Which animal is closest to a gazelle?','an antelope','a penguin','a salmon','gazelle 属羚羊类。')]);
P('gazette','gazette 经意大利语 gazzetta 和法语进入英语，可作名词指刊登官方公告的定期出版物或报纸，也可作动词表示在公报上正式公布。',C('gazette.s2','行政公告','The ministry gazetted the revised border rules on Monday, making the change official before the new permits were issued.','部委周一在公报上公布了修订后的边境规则，使变更在新许可证发放前正式生效。','The ministry gazetted the revised border rules on Monday / making the change official / before the new permits were issued.','gazette 作动词表示在官方公报刊载、公布；making 说明正式公告的作用。','部门正式刊载规则，符合 s2。'),M('The agency gazetted the regulation by hiding it from the public and never publishing it.','The agency withheld the regulation by hiding it from the public and never publishing it.','不予刊载、对公众隐瞒与在官方公报公布相反。'),[Q('gazette',1,1,'An official gazette is a publication that may print?','government notices and formal announcements','only private family photographs','weather readings from one thermometer','gazette 可指刊载官方公告的期刊。'),Q('gazette',2,2,'To gazette a new regulation is to?','announce it officially in a gazette','erase it from every public record','estimate its cost informally','动词 gazette 表示正式公告。'),Q('gazette',3,1,'A local gazette may also be?','a newspaper','a type of antelope','a kitchen on an aircraft','gazette 也可指报纸。'),Q('gazette',4,2,'Which sentence uses gazette as a verb?','The council gazetted the new boundary.','The gazette arrived by post.','She read the weekly gazette.','gazetted 作动词表示刊载正式公告。')]);
P('genealogist','genealogist 由 genealogy（家谱学、系谱学）加 -ist 构成，指追查家族历史、世系和亲属关系的专家或研究者。',C('genealogist.s1','家族史研究','The genealogist compared parish registers, immigration records, and family letters to confirm how the two branches of the family were related.','家谱研究者比较教区登记、移民档案和家书，以确认这个家族的两个分支有何亲属关系。','The genealogist compared parish registers, immigration records, and family letters / to confirm / how the two branches of the family were related.','genealogist 是研究家族世系的人；to confirm 表明其使用史料核对关系。','研究者通过历史记录追查亲属关系，符合词义。'),M('The genealogist traced the family tree by studying only the chemical composition of rocks.','The geologist studied the chemical composition of rocks, while the genealogist traced family relationships.','岩石成分属于地质学研究，不是家谱研究。'),[Q('genealogist',1,1,'A genealogist studies?','family histories and relationships','the chemical processes inside the Earth','the rules of geometric proof','genealogist 研究家族谱系。'),Q('genealogist',2,1,'Which record might help a genealogist?','a century-old birth register','a recent weather forecast','a list of chemical elements only','出生登记可帮助追查家族关系。'),Q('genealogist',3,1,'A genealogist may build?','a family tree from records and interviews','a railway feeder line','a semiconductor generator','家谱研究者常重建家族树。'),Q('genealogist',4,1,'The closest related field to a genealogist’s work is?','family-history research','electrical engineering','marine birdwatching','家谱学研究家庭历史。')]);
P('generalisation','generalisation 是英式拼法，由 generalise 加 -ation 构成，指从具体例子提出一般陈述，也可指作出概括的过程。',C('generalisation.s1','研究写作','The report’s generalisation that every rural school lacks technology was unsupported because the author had visited only one district.','报告概括说所有乡村学校都缺乏技术设备，但作者只走访了一个地区，因此这一概括缺乏依据。','The report’s generalisation / that every rural school lacks technology / was unsupported / because the author had visited only one district.','generalisation 后的 that 从句呈现一般性主张；because 解释证据覆盖不足。','从一个地区推及所有学校，是由有限案例形成的概括。'),M('The report’s generalisation was reliable because it described one named classroom and made no claim about other schools.','The report’s observation was limited to one named classroom and made no claim about other schools.','只描述单一教室、未推广到其他学校，不是 generalisation。'),[Q('generalisation',1,1,'A generalisation is?','a broad statement drawn from particular cases','a single exact measurement with no wider claim','a list of names in alphabetical order','generalisation 指由具体事例作出的概括。'),Q('generalisation',2,1,'Why can a generalisation from one interview be risky?','one case may not represent a whole population','an interview can never contain information','general statements are always numerical','单一案例未必能代表整体。'),Q('generalisation',3,1,'Which is a generalisation?','All city residents prefer buses, based on three interviews.','One interviewee said she prefers the bus.','The bus arrived at 8:14 today.','把有限访谈推广到全体居民是概括。'),Q('generalisation',4,1,'Generalisation is closest to?','broad inference','single observation','private correspondence','broad inference 表示由个别情况作广泛推断。')]);
P('generalise','generalise 是英式拼法，由 general 加 -ise 构成，表示从具体事实归纳一般说法，也可指把某个想法推广到更多情境。',C('generalise.s1','证据推论','Researchers should not generalise from one unusually successful school to all schools without checking whether the same conditions apply elsewhere.','研究人员不应从一所表现异常优秀的学校就推及所有学校，而不先核实其他地方是否具备相同条件。','Researchers should not generalise from one unusually successful school to all schools / without checking / whether the same conditions apply elsewhere.','generalise from A to B 表示由个别案例推及整体；without 引出缺少的验证步骤。','单一学校不足以支持面向所有学校的一般结论。'),M('The researchers generalised their claim by refusing to apply it beyond the one case they had studied.','The researchers limited their claim by refusing to apply it beyond the one case they had studied.','拒绝推广结论是限制适用范围，不是 generalise。'),[Q('generalise',1,1,'To generalise from a sample is to?','draw a broader statement from particular cases','record each case without comparison','delete every observation','generalise 表示从个例归纳。'),Q('generalise',2,1,'A team generalises a successful method when it?','applies the idea to other settings','keeps the method in one file unused','changes the method’s name only','把方法推广到其他环境是 s2。'),Q('generalise',3,1,'Which conclusion overgeneralises?','One patient improved, so this treatment cures everyone.','This patient improved after treatment.','A larger trial is needed to estimate effectiveness.','从单个患者推广到所有人缺乏充分依据。'),Q('generalise',4,1,'Generalise is the British spelling of?','generalize','generalization','generally','英式 generalise 对应美式 generalize。')]);
P('generalist','generalist 由 general 加 -ist 构成，指知识或技能覆盖多个领域、而非只专攻一个狭窄专业的人。',C('generalist.s1','职业分工','The small clinic hired a generalist who could handle routine equipment checks, basic data entry, and several kinds of administrative support.','这家小诊所聘用了一位多面手，能处理常规设备检查、基础数据录入和多种行政支持工作。','The small clinic hired a generalist / who could handle routine equipment checks, basic data entry, / and several kinds of administrative support.','generalist 指知识或工作范围广的人；who 从句列举其跨领域任务。','该员工承担多类常规工作，而非单一专科，符合词义。'),M('The generalist worked exclusively on one microscopic task and had no knowledge outside that specialty.','The specialist worked exclusively on one narrow task and had no knowledge outside that specialty.','只从事单一狭窄领域的人是 specialist，不是 generalist。'),[Q('generalist',1,1,'A generalist is a person whose knowledge?','covers several areas rather than one narrow specialty','is limited to one tiny technical procedure','contains no practical information','generalist 指多领域通才。'),Q('generalist',2,1,'A small organization may value a generalist because the person can?','take on varied kinds of work','perform only one fixed operation','avoid learning any new task','多面手可以承担不同种类的工作。'),Q('generalist',3,1,'Which worker is a generalist?','a staff member handling basic IT, scheduling, and records','a surgeon who only performs one specialized operation','a machine that generates electricity','跨 IT、排班与记录工作体现通才特点。'),Q('generalist',4,1,'The closest contrast to generalist is?','specialist','all-rounder','multiskilled worker','specialist 指专才。')]);
P('generalizable','generalizable 由 generalize 加 -able 构成，表示结论、方法或结果能够合理推广到其他情境；英式常拼 generalisable。',C('generalizable.s1','研究方法','The result may be generalizable to similar clinics because the study included varied patients and repeated the protocol at several sites.','由于研究纳入了不同患者，并在多个地点重复执行方案，这项结果或可推广到类似诊所。','The result may be generalizable to similar clinics / because the study included varied patients / and repeated the protocol at several sites.','generalizable to + 群体或环境；may 表示推广适用仍有条件。','多地点重复和样本多样性为推广到相似环境提供依据。'),M('The result is generalizable to every country because it was measured once in a single clinic.','The result may not be generalizable beyond that clinic because it was measured only once in one setting.','单地点一次测量无法支持推广到所有国家。'),[Q('generalizable',1,1,'A finding is generalizable when it?','can reasonably apply beyond the cases studied','is true only for one named individual','cannot be checked by anyone','generalizable 表示可推广到其他情况。'),Q('generalizable',2,1,'What strengthens a study’s generalizability?','replication across varied sites and participants','one unrepeatable observation','excluding every unusual case without explanation','多地点和多样样本提高外推能力。'),Q('generalizable',3,1,'A result from one tiny sample may be?','not generalizable to a whole country','automatically universal','unrelated to its sample size','小样本结果未必适用于整个国家。'),Q('generalizable',4,1,'Generalizable is closest to?','applicable more broadly','strictly local','impossible to repeat','可更广泛适用与 generalizable 接近。')]);
P('generalization','generalization 由 generalize 加 -ation 构成，可指由少数例子形成的宽泛主张，也可指形成这种概括的过程。',C('generalization.s1','逻辑论证','The reviewer rejected the generalization that remote workers are less productive because the survey measured hours online, not completed work.','评论者驳回了“远程员工效率更低”这一概括，因为调查测的是在线时长，而非完成的工作量。','The reviewer rejected the generalization / that remote workers are less productive / because the survey measured hours online / not completed work.','generalization 后的 that 从句是宽泛主张；because 解释指标不能支持该结论。','由不充分指标对所有远程员工下结论，属于不可靠的泛化。'),M('The reviewer called the claim a generalization although it reported only the exact result for one named worker.','The reviewer called the claim a specific observation because it reported only the exact result for one named worker.','只报告单个对象的具体结果不是宽泛概括。'),[Q('generalization',1,1,'A generalization from a few examples is?','a broad claim that may exceed the evidence','a direct copy of one observation','a device that stores laboratory samples','generalization 可指根据少数例子作出的宽泛主张。'),Q('generalization',2,1,'Which statement is an unsafe generalization?','Two delayed buses prove the entire transit system is always late.','The 8:00 bus arrived late today.','We need more data before judging the route.','由两班车推断整个系统永远迟到，范围过宽。'),Q('generalization',3,1,'A scientist improves a generalization by?','testing whether it holds across additional cases','ignoring every case that disagrees','making the claim broader without evidence','增加案例检验能判断概括是否成立。'),Q('generalization',4,1,'In logic, generalization is closest to?','induction from cases','a single measurement','a verb tense','由具体案例归纳是 generalization 的核心过程。')]);
P('generalize','generalize 是 general 加 -ize 构成的美式常用拼法，可表示用一般措辞表达，也可指将想法或做法推广应用。',C('generalize.s2','技术推广','After testing the scheduling tool in two departments, the company decided to generalize the method to its other offices.','在两个部门测试排班工具后，公司决定把这套方法推广到其他办公室。','After testing the scheduling tool in two departments / the company decided / to generalize the method / to its other offices.','generalize A to B 表示把 A 推广到 B；after 从句说明先行测试。','把方法从两个部门扩展到其他办公室，符合推广义 s2。'),M('The company generalized the tool to other offices by refusing to use it anywhere outside the pilot department.','The company confined the tool to the pilot department by refusing to use it elsewhere.','拒绝在试点外使用是限制应用，不是推广。'),[Q('generalize',1,1,'To generalize a conclusion is to?','state it in broader terms','remove every broad claim','measure a single object exactly','generalize 可指把结论概括表达。'),Q('generalize',2,2,'To generalize a method across offices is to?','apply it more widely','keep it restricted to one room','replace it with an unrelated method','s2 指使某方法广泛应用。'),Q('generalize',3,1,'Which action generalizes a successful procedure?','adopting it in several new branches','using it once and then deleting it','keeping it secret from all other teams','在多个新分支采用是推广应用。'),Q('generalize',4,1,'Generalize is the American spelling corresponding to British?','generalise','generalization','generalizable','英式动词常写 generalise。')]);
P('generative','generative 由 generate 加 -ive 构成，表示能够产生新事物、后代或语言结构；具体意义取决于领域。',C('generative.s1','计算语言学','The generative model produced several grammatical sentences from a short prompt, but editors still checked each output for factual accuracy.','生成模型根据简短提示产出了若干语法通顺的句子，但编辑仍逐条核查输出是否符合事实。','The generative model produced several grammatical sentences / from a short prompt / but editors still checked each output / for factual accuracy.','generative 修饰 model，表示它能生成新内容；but 说明生成能力不等于准确性。','模型根据提示产出新句子，体现 generative 的生成能力。'),M('The generative system could produce nothing new and only stored a fixed list of old sentences.','The archival system could produce nothing new and only stored a fixed list of old sentences.','只储存固定内容且不能生成输出的系统不是 generative。'),[Q('generative',1,1,'A generative system can?','produce new outputs from rules or inputs','only repeat one fixed label','measure the height of a building','generative 指有生成新内容的能力。'),Q('generative',2,1,'In biology, generative tissue may be tissue that?','produces new cells or offspring structures','prevents every form of growth','stores electricity for a motor','生物义可指产生新细胞或繁殖结构。'),Q('generative',3,1,'A generative grammar aims to?','describe rules that can produce sentences','list only words without structure','translate rocks into minerals','生成语法用规则产生句子。'),Q('generative',4,1,'Which contrast best fits generative capacity?','creating new examples versus retrieving only fixed records','measuring a distance versus measuring a height','speaking quietly versus loudly','产生新内容与只检索固定记录相对。')]);
P('generator','generator 由 generate 加施事者后缀 -or 构成，可指发电机，也可泛指任何产生电力、信号或其他结果的装置或来源。',C('generator.s1','应急供电','The hospital tested its backup generator each month so that essential monitors would keep running during a power cut.','医院每月测试备用发电机，以确保停电时关键监护设备仍能运行。','The hospital tested its backup generator each month / so that essential monitors / would keep running / during a power cut.','generator 作可数名词指发电机；so that 引出备用设备的用途。','设备在停电时提供电力，符合 s1。'),M('The generator stopped producing electricity and was used only to store empty boxes.','The storage cabinet stopped producing electricity and was used only to store empty boxes.','存放箱子的柜子不是发电机。'),[Q('generator',1,1,'A backup generator is a machine that?','produces electricity','stores food at a low temperature','measures a person’s gait','generator 可指发电机。'),Q('generator',2,2,'A password generator is something that?','produces passwords','repairs a power cable','records a family tree','generator 也可泛指产生某类东西的装置。'),Q('generator',3,1,'Why test a hospital generator?','to ensure it can supply power during an outage','to confirm it can print patient records','to make the building use more water','发电机用于断电时供电。'),Q('generator',4,1,'A generator differs from a battery in that a generator typically?','produces electrical power from another energy source','stores only written instructions','measures how much fuel remains without producing power','发电机把其他形式的能量转为电力。')]);
P('generic','generic 经法语源自拉丁语 genericus，与 genus“类别、种类”有关，可指非特定品牌的、属于某一类别的，也可指非专利药。',C('generic.s3','药品购买','The pharmacist offered a generic version of the medicine with the same active ingredient, explaining that it was sold without the original brand name.','药剂师提供了这种药的非专利版本，说明其活性成分相同，但不以原品牌名称销售。','The pharmacist offered a generic version of the medicine / with the same active ingredient / explaining that it was sold / without the original brand name.','generic 作药品形容词指非专利、通用名药；without 引出品牌特征。','药品含相同活性成分但没有原品牌名，符合 s3。'),M('The generic medicine was sold under the original company’s exclusive brand and patented name.','The branded medicine was sold under the original company’s exclusive brand and patented name.','带原公司独家品牌和专利名的药不是 generic medicine。'),[Q('generic',1,1,'A generic description is?','not specific to one named brand or item','limited to one exact person','a detailed family tree','generic 可指一般的、非特定的。'),Q('generic',2,2,'A generic feature applies to?','a whole class or group','only one named individual','a single hour on a clock','generic 可指适用于一整类事物。'),Q('generic',3,3,'A generic medicine is commonly sold?','without the original brand name','only under the inventor’s exclusive label','as a type of seabird','generic drug 指非专利品牌药。'),Q('generic',4,1,'Which is a generic instruction?','“Wear suitable footwear.”','“Mina must wear her red boots at 9:00.”','“Use model XZ-14 only.”','不指定品牌或个人的指令更一般、非特定。')]);
P('generically','generically 由 generic 加 -ally 构成，表示按类别或一般方式称呼，而不指定某个具名个体或品牌。',C('generically.s1','生物命名','In the field guide, the plant was referred to generically as a “wild onion” before the botanist supplied its exact species name.','在野外指南中，这种植物先被泛称为“野洋葱”，随后植物学家才给出其确切物种名。','In the field guide / the plant was referred to generically as a “wild onion” / before the botanist supplied / its exact species name.','generically 修饰 referred to，表示按一般类别称呼；before 对照俗称与精确名称。','先使用类别俗称而非具名物种，符合 generically。'),M('The label referred to the sample generically by giving its exact scientific species and unique catalog number.','The label referred to the sample specifically by giving its exact scientific species and unique catalog number.','提供唯一编号和准确物种名属于具体指称，不是 generically。'),[Q('generically',1,1,'To refer to an item generically is to?','name its type without identifying a unique brand or individual','give its exact serial number','describe only its color','generically 表示按类别泛称。'),Q('generically',2,1,'A shop calls several tissues “paper products” generically because it?','uses a broad category name','lists every brand and model','identifies one exact sheet by number','宽泛类别名不指定具体品牌。'),Q('generically',3,1,'Which phrase is used generically?','a bird, without naming its species','the tagged gannet number 18','the exact model and serial code','bird 是一般类别称谓。'),Q('generically',4,1,'The closest opposite of generically is?','specifically','broadly','by type','specifically 表示具体地。')]);
P('generously','generously 由 generous 加 -ly 构成；generous 经古法语与拉丁语 generosus“出身高贵、慷慨”发展，表示慷慨地、大量地或宽厚地。',C('generously.s1','社区互助','The restaurant generously donated its evening surplus to the shelter, packaging the meals safely before volunteers collected them.','餐馆慷慨地把晚间剩余食物捐给收容所，并在志愿者来取之前妥善打包。','The restaurant generously donated its evening surplus to the shelter / packaging the meals safely / before volunteers collected them.','generously 修饰 donated，表示慷慨给予；packaging 补充捐赠时的准备。','无偿捐出剩余食物体现慷慨。'),M('The donor generously gave nothing and refused to share even a small amount of food.','The donor selfishly gave nothing and refused to share even a small amount of food.','拒绝给予体现自私，不是 generous。'),[Q('generously',1,1,'To give generously is to give?','freely and in a willing or abundant way','only after being forced to do so','nothing at all','generously 表示慷慨地给予。'),Q('generously',2,1,'A generously sized portion is?','larger than a small or minimal serving','too tiny to see','measured exactly as zero','generously 也可表示量大、充足。'),Q('generously',3,1,'A host acts generously by?','welcoming guests and sharing food freely','charging guests for every glass of water','refusing to offer a seat','热情款待并分享食物体现慷慨。'),Q('generously',4,1,'Which is the closest contrast to generously?','stingily','kindly','lavishly','stingily 表示吝啬地。')]);
P('genesis','genesis 来自希腊语 genesis“起源、诞生”，指事物开始存在或形成的起点。',C('genesis.s1','项目沿革','The genesis of the neighborhood garden was a small group of residents who began planting herbs in an unused lot.','社区花园的起源是一小群居民，他们最初在一块闲置地上种植香草。','The genesis of the neighborhood garden / was a small group of residents / who began planting herbs / in an unused lot.','the genesis of + 事物表示其起源；who 从句交代最初行动。','居民的早期种植活动是社区花园形成的起点。'),M('The genesis of the bridge was its final inspection, which took place after construction ended.','The genesis of the bridge was its initial design and planning, which began before construction.','竣工后的验收是项目末期，不是起源。'),[Q('genesis',1,1,'The genesis of a project is?','its origin or beginning','its final review only','its current price','genesis 指起源、形成。'),Q('genesis',2,1,'A historian studies the genesis of a law to learn?','how and why it first came into being','which office cleans the courthouse','how tall the law book is','研究法律起源就是了解其形成过程。'),Q('genesis',3,1,'Which event marks the genesis of a club?','the first meeting where members formed it','the club’s tenth anniversary','the last member leaving','首次创立会议标志起点。'),Q('genesis',4,1,'The closest synonym for genesis is?','origin','aftermath','decoration','origin 表示起源。')]);
P('genetic','genetic 由 genetics/gene 词族加 -ic 构成，现代主要指基因或遗传；较旧用法可表示关于起源的。',C('genetic.s1','医学遗传','The genetic test found a variant associated with the disorder, but the counselor explained that the result alone could not predict exactly how severe symptoms would be.','基因检测发现了一种与该疾病有关的变异，但遗传咨询师解释说，仅凭这一结果无法准确预测症状会有多严重。','The genetic test found a variant / associated with the disorder / but the counselor explained / that the result alone could not predict exactly how severe symptoms would be.','genetic 修饰 test 和 variant，表示与基因有关；but 限定检测结果的预测能力。','检测涉及与疾病相关的基因变异，体现现代 s1。'),M('The genetic test measured only the patient’s shoe size and had no connection to genes or inheritance.','The orthopedic assessment measured the patient’s shoe size and had no connection to genes or inheritance.','鞋码测量与基因无关，不能称 genetic test。'),[Q('genetic',1,1,'A genetic trait is related to?','genes or heredity','the geometry of a building','the price of a newspaper','现代 genetic 常指基因或遗传。'),Q('genetic',2,2,'In an older scholarly use, a genetic account may discuss?','the origin or development of something','a person’s inherited DNA only','the shape of a triangle','genetic 的旧义可与事物起源有关。'),Q('genetic',3,1,'Which is a genetic question?','whether a condition runs in a family','whether a bridge is geometrically level','whether a gazette was printed on Tuesday','家族遗传风险属于 genetic 问题。'),Q('genetic',4,1,'A genetic counselor may explain?','how inherited variants relate to health risk','how to repair a gas lamp','how to identify Greek letters','遗传咨询涉及基因与健康风险。')]);
P('genetically','genetically 由 genetic 加 -ally 构成，表示由基因决定、通过遗传方式，或从遗传学角度而言。',C('genetically.s1','农业育种','The two tomato varieties are genetically distinct, even though their fruit looks similar, because laboratory analysis found different inherited markers.','这两个番茄品种虽然果实外观相似，但在遗传上不同，因为实验室分析发现了不同的遗传标记。','The two tomato varieties are genetically distinct / even though their fruit looks similar / because laboratory analysis found / different inherited markers.','genetically 修饰 distinct，说明差异基于遗传信息；even though 对照外观。','遗传标记不同说明品种在基因层面有差异。'),M('The plants were genetically identical because laboratory tests found different inherited markers in every sample.','The plants were genetically different because laboratory tests found different inherited markers in every sample.','不同遗传标记说明样本并非 genetically identical。'),[Q('genetically',1,1,'Two organisms are genetically related if they?','share inherited material through ancestry','live in the same greenhouse only','have the same color by chance','genetically 表示与基因遗传有关。'),Q('genetically',2,1,'A crop is genetically modified when?','its genetic material has been deliberately altered','its leaves are trimmed with scissors','its seeds are stored in a paper bag','遗传物质被改变即属于 genetically modified。'),Q('genetically',3,1,'A disease is genetically inherited when it?','can pass through genes from parent to child','is caused only by a broken streetlight','spreads solely through a newspaper','基因可把某些疾病风险传递给后代。'),Q('genetically',4,1,'Which phrase is natural?','genetically diverse plants','geneticly diverse plants','genetically diversity plants','副词 genetically 修饰形容词 diverse。')]);
P('genetics','genetics 由 genetic 加学科后缀 -ics 构成，指研究基因、遗传及性状传递规律的生物学分支。',C('genetics.s1','实验室研究','The genetics course taught students how researchers track inherited traits through pedigrees and compare DNA markers across generations.','遗传学课程教学生如何通过家系图追踪遗传性状，并比较不同世代的 DNA 标记。','The genetics course taught students / how researchers track inherited traits through pedigrees / and compare DNA markers / across generations.','genetics 是学科名称；how 从句列出研究方法。','课程研究性状遗传与 DNA 标记，符合遗传学定义。'),M('Genetics is the study of weather fronts, cloud formation, and ocean tides.','Meteorology studies weather fronts and clouds, while oceanography studies tides.','气象与海洋现象不属于 genetics。'),[Q('genetics',1,1,'Genetics is the branch of biology that studies?','genes and inherited traits','the motion of planets only','the design of bridges','genetics 研究基因及遗传性状。'),Q('genetics',2,1,'A genetics researcher might compare?','DNA from relatives across generations','different paint colors on a wall','the gaits of two unrelated horses only','遗传研究可比较亲属 DNA。'),Q('genetics',3,1,'Which question belongs to genetics?','How is a trait passed from parent to child?','How fast does a river flow today?','What is the price of a newspaper?','性状如何遗传属于遗传学。'),Q('genetics',4,1,'A family pedigree is useful in genetics because it?','shows patterns of inherited traits','maps a railway feeder road','lists the parts of a gas generator','家系图帮助研究遗传模式。')]);
P('genial','genial 经拉丁语 genialis“宜人、使人愉快的”进入英语，可形容亲切开朗的人，也可形容温和宜人的天气或气候。',C('genial.s2','气候描写','A genial spring afternoon encouraged residents to open the windows and walk to the market instead of taking the bus.','一个温和宜人的春日下午让居民愿意开窗，并步行去集市而不坐公交。','A genial spring afternoon encouraged residents / to open the windows / and walk to the market / instead of taking the bus.','genial 修饰天气，表示温暖舒适；encourage somebody to do 描述其影响。','宜人的春日天气促使人们外出，符合 s2。'),M('The genial weather froze the pipes, drove everyone indoors, and made the afternoon dangerously cold.','The bitterly cold weather froze the pipes, drove everyone indoors, and made the afternoon dangerously cold.','严寒结冰与温和宜人的 genial 天气相反。'),[Q('genial',1,1,'A genial host is?','friendly, cheerful, and easy to talk to','rude and unwilling to greet anyone','an expert in family history','genial 可形容亲切友好的主人。'),Q('genial',2,2,'Genial weather is?','pleasantly mild and warm','severely freezing and harsh','completely unrelated to climate','genial 的气候义是温和宜人。'),Q('genial',3,1,'Which person seems genial?','a welcoming neighbor who chats warmly with visitors','a host who insults every guest','a clerk who refuses to answer','热情友好体现 genial。'),Q('genial',4,2,'A genial breeze on a spring day would feel?','mild and pleasant','icy and painful','hot enough to scorch the ground','温和舒适的微风符合 s2。')]);
P('genotype','genotype 是 gene 与 type 的组合，指生物携带的基因组成；它不等同于个体可观察到的全部表现型。',C('genotype.s1','遗传学实验','The researchers identified the plant’s genotype from its DNA markers, then compared the result with the flower color observed in the greenhouse.','研究人员根据 DNA 标记确定了这种植物的基因型，然后把结果与温室里观察到的花色进行比较。','The researchers identified the plant’s genotype from its DNA markers / then compared the result / with the flower color observed / in the greenhouse.','genotype 指基因组成；then 对照基因信息与可观察性状。','DNA 标记用于确定基因构成，符合 genotype。'),M('The genotype is the visible flower color itself, regardless of the organism’s genes.','The phenotype is the visible flower color, while the genotype is the organism’s genetic makeup.','可见花色是表现型 phenotype，不是基因组成 genotype。'),[Q('genotype',1,1,'An organism’s genotype is its?','set of genes or genetic makeup','visible color alone','place where it lives','genotype 指基因组成。'),Q('genotype',2,1,'Which evidence can help identify a genotype?','DNA markers','the organism’s shadow length only','the price of its food','DNA 标记有助于识别基因型。'),Q('genotype',3,1,'How does genotype differ from phenotype?','genotype is genetic makeup; phenotype is observable traits','genotype is habitat; phenotype is ancestry','the two words always mean exactly the same thing','基因型是基因组成，表现型是观察到的特征。'),Q('genotype',4,1,'A genotype may be studied to learn?','which inherited variants an organism carries','whether a room is brightly decorated','which Greek letter comes third','基因型能显示个体携带的遗传变异。')]);
P('genteel','genteel 经法语 gentil“高贵、文雅”发展，形容带有上流阶层礼仪的举止或风格，有时暗含过分讲究体面、做作。',C('genteel.s1','社会风格','The novel portrays a genteel household where guests observe elaborate manners, polished conversation, and strict expectations about formal dress.','小说描绘了一个讲究体面的家庭，宾客遵守繁复礼仪、谈吐文雅，并严格要求穿着正式。','The novel portrays a genteel household / where guests observe elaborate manners / polished conversation / and strict expectations about formal dress.','genteel 修饰 household，指其礼仪风格符合上层社会的体面规范。','繁复礼仪和正式着装构成传统 genteel 风格。'),M('The genteel gathering encouraged guests to shout insults, throw food, and ignore every courtesy.','The rowdy gathering encouraged guests to shout insults, throw food, and ignore every courtesy.','粗野喧闹、无视礼节与 genteel 的文雅体面相反。'),[Q('genteel',1,1,'A genteel manner is associated with?','polished manners linked to high social class','deliberate rudeness and disorder','technical knowledge of genes','genteel 指有教养、讲究体面的。'),Q('genteel',2,1,'A genteel tea party might feature?','formal greetings and carefully served tea','guests throwing cups at one another','a debate about electrical wiring only','正式礼仪和精心招待符合 genteel 风格。'),Q('genteel',3,1,'Why can genteel sometimes sound critical?','it may suggest affected or excessive social refinement','it always means physically strong','it identifies a genetic condition','有时暗含矫饰、过度讲究体面。'),Q('genteel',4,1,'The closest contrast to genteel behavior is?','boorish behavior','courteous behavior','refined behavior','boorish 表示粗鲁无礼。')]);
P('gentility','gentility 由 genteel/gentle 词族加 -ity 构成，可指上流阶层的文雅礼仪，也可集合指具有较高社会地位的人群。',C('gentility.s2','社会史','The memoir describes how the landed gentility gathered at the county house for elections, estate business, and seasonal celebrations.','回忆录描写了拥有土地的上层人士如何聚集在郡宅，参加选举、庄园事务和季节性庆典。','The memoir describes / how the landed gentility gathered at the county house / for elections, estate business, / and seasonal celebrations.','gentility 可集合指社会上层人士；landed 修饰拥有土地的阶层。','土地所有者群体聚集处理事务，体现 s2 的阶层义。'),M('The village gentility referred to every resident regardless of status and had no connection with social class.','The village population referred to every resident regardless of status and had no connection with social class.','不分社会地位的全体居民不是上流阶层 gentility。'),[Q('gentility',1,1,'Gentility in a person refers to?','refined and polite manners','a loud and aggressive temper','the ability to measure a triangle','gentility 可指温文尔雅的举止。'),Q('gentility',2,2,'The landed gentility were?','people of higher social rank who owned land','all residents of a town without distinction','a group of geologists','s2 指社会上层人士这一群体。'),Q('gentility',3,1,'Which behavior shows gentility?','speaking courteously and observing formal manners','interrupting every guest and mocking them','refusing to acknowledge any greeting','礼貌待人并遵守礼节体现 gentility。'),Q('gentility',4,1,'The closest contrast to gentility of manners is?','boorishness','refinement','courtesy','boorishness 表示粗野无礼。')]);
P('gentlemanly','gentlemanly 由 gentleman 加 -ly 构成，形容有礼貌、公平而举止得体的行为，不限于男性身份。',C('gentlemanly.s1','体育精神','After losing the match, the captain made a gentlemanly speech, congratulating the opponents and thanking the officials for their fair decisions.','输掉比赛后，队长发表了彬彬有礼的讲话，祝贺对手并感谢裁判公正执裁。','After losing the match / the captain made a gentlemanly speech / congratulating the opponents / and thanking the officials for their fair decisions.','gentlemanly 修饰 speech，体现礼貌、公平；分词短语列出讲话内容。','即使失利仍礼貌祝贺并感谢裁判，体现 gentlemanly。'),M('His gentlemanly conduct involved insulting the opponents and refusing to shake hands.','His unsportsmanlike conduct involved insulting the opponents and refusing to shake hands.','侮辱对手并拒绝握手与 gentlemanly 的礼貌、公平相反。'),[Q('gentlemanly',1,1,'A gentlemanly response to defeat is?','congratulating the winner and accepting the result fairly','accusing the winner without evidence','breaking the equipment in anger','失利后公平祝贺对方体现有礼风度。'),Q('gentlemanly',2,1,'Gentlemanly behavior is best described as?','courteous and fair','rude and boastful','quiet only because of fear','gentlemanly 指礼貌、公正而得体。'),Q('gentlemanly',3,1,'Which action is gentlemanly?','returning a lost wallet to its owner','keeping the wallet and denying finding it','laughing at a rival’s injury','诚实归还失物体现得体行为。'),Q('gentlemanly',4,1,'The closest contrast to gentlemanly conduct is?','boorish conduct','courteous conduct','fair conduct','boorish 表示粗鲁无礼。')]);
P('gentleness','gentleness 由 gentle 加 -ness 构成，指温和、体贴的态度或触感柔和、不粗暴的性质。',C('gentleness.s1','照护与触感','The nurse handled the frightened child with gentleness, explaining each step softly and pausing whenever the child needed reassurance.','护士温柔地照顾受惊的孩子，轻声解释每一步，并在孩子需要安慰时停下来。','The nurse handled the frightened child with gentleness / explaining each step softly / and pausing / whenever the child needed reassurance.','with gentleness 表示以温柔方式对待；whenever 引出照护中的调整。','护士以体贴、不强迫的方式回应孩子的恐惧，体现温柔。'),M('The nurse showed gentleness by shouting at the child and forcing each movement without warning.','The nurse showed impatience by shouting at the child and forcing each movement without warning.','喊叫并强迫动作是粗暴不耐烦，不是 gentleness。'),[Q('gentleness',1,1,'Gentleness in a caregiver is?','kindness and a soft, considerate manner','forceful treatment without listening','the skill of measuring a room','gentleness 指温柔体贴。'),Q('gentleness',2,1,'A touch with gentleness would be?','light and careful','rough enough to cause pain','so forceful that it knocks someone down','轻柔小心的触碰体现 gentleness。'),Q('gentleness',3,1,'Which response shows gentleness?','comforting someone with a calm voice','mocking them for being upset','ordering them to stop crying immediately','平静安慰而非责骂体现温和。'),Q('gentleness',4,1,'A close contrast to gentleness is?','harshness','kindness','softness','harshness 表示粗暴、严厉。')]);
P('gentry','gentry 经古法语 genterie 发展，历史上指贵族之下、拥有土地的绅士阶层；现代可泛指上层社会群体。',C('gentry.s1','英国社会史','The local gentry controlled several estates and often served as magistrates, though they ranked below the hereditary aristocracy.','当地乡绅拥有数处庄园，也常担任治安法官，尽管其地位低于世袭贵族。','The local gentry controlled several estates / and often served as magistrates / though they ranked below / the hereditary aristocracy.','gentry 是集合名词；though 从句说明其社会等级位置。','有土地、地位高于普通人但低于贵族的群体符合历史义。'),M('The gentry were all factory laborers with no land or social standing.','The working class were factory laborers with no land or high social standing.','工厂劳动者并非历史上拥有土地的 gentry 阶层。'),[Q('gentry',1,1,'Historically, the gentry were?','landed people below the aristocracy in social rank','every person in a town regardless of status','a group of seabirds nesting on cliffs','gentry 指贵族以下的上层土地所有者。'),Q('gentry',2,1,'A manor’s local gentry might have?','land, influence, and roles in county affairs','no property or standing in the community','a job measuring electrical current','乡绅常拥有土地并参与地方事务。'),Q('gentry',3,1,'Which group is closest to the historical gentry?','wealthy landowners below the nobility','all wage laborers in a factory','a team of geneticists','历史 gentry 是贵族以下的土地所有者。'),Q('gentry',4,1,'The gentry is a social class, not?','a species of bird','a class of people','a group ranked by status','gentry 是阶层名称而非鸟类。')]);
P('genu','genu 是拉丁语“膝”的医学拉丁形式，常见于解剖学或临床术语，例如 genu valgum（膝外翻）。',C('genu.s1','解剖学术语','In the anatomical label genu, the term refers to the knee joint; the lecture used it to explain the Latin element in several clinical expressions.','在解剖学标注中，genu 指膝关节；讲座用它解释若干临床表达中的拉丁词素。','In the anatomical label genu / the term refers to the knee joint / the lecture used it / to explain the Latin element in several clinical expressions.','genu 是解剖学拉丁词，指膝；此处说明术语含义而非提供诊断。','该词直接对应拉丁语“膝”，用于医学术语。'),M('In the anatomical term genu, the word means the elbow joint.','In the anatomical term genu, the word means the knee joint.','genu 指膝，不是肘。'),[Q('genu',1,1,'In medical Latin, genu refers to the?','knee','elbow','ankle','genu 的含义是膝。'),Q('genu',2,1,'The term genu valgum concerns the?','knee alignment','shape of the ear','movement of the wrist','genu valgum 是涉及膝部的术语。'),Q('genu',3,1,'Which translation matches genu?','knee','shoulder','jaw','genu 对应 knee。'),Q('genu',4,1,'Genu is most likely encountered in?','an anatomical or medical term','a recipe for bread','a newspaper weather column','genu 常见于解剖学和医学术语。')]);
P('genuinely','genuinely 由 genuine 加 -ly 构成，genuine 经法语源自拉丁语 genuinus“本真的、出自本性的”，表示真实地、由衷地而非装出来的。',C('genuinely.s1','人际交流','Mara was genuinely pleased when her colleague received the award, and she congratulated him without comparing their careers.','同事获奖时，玛拉由衷地为他高兴，并真诚祝贺，没有拿两人的职业生涯作比较。','Mara was genuinely pleased / when her colleague received the award / and she congratulated him / without comparing their careers.','genuinely 修饰 pleased，强调情绪真诚；without 表示没有嫉妒或做作。','她真诚高兴并主动祝贺，符合 genuinely。'),M('He was genuinely grateful but only pretended to say thank you and felt no appreciation at all.','He was not genuinely grateful; he only pretended to say thank you and felt no appreciation at all.','完全没有感激之情却说 genuininely grateful，自相矛盾。'),[Q('genuinely',1,1,'If someone is genuinely happy, the happiness is?','real and sincere','pretended for an audience','based on a false label','genuinely 表示真实、由衷。'),Q('genuinely',2,1,'A genuinely useful tool?','actually helps with the task','looks helpful but never works','is praised only by its inventor','真正有用意味着确实能帮助完成任务。'),Q('genuinely',3,1,'Which apology sounds genuine?','“I am sorry for interrupting; I should have listened.”','“I am sorry you noticed me interrupting.”','“I never interrupt,” said while continuing to do so.','承认自己的行为并表达歉意更真诚。'),Q('genuinely',4,1,'The closest contrast to genuinely is?','insincerely','truly','sincerely','insincerely 表示不真诚地。')]);
P('geobotany','geobotany 由 geo-（地球、地理）与 botany（植物学）组成，研究植物的地理分布及其与环境的关系。',C('geobotany.s1','植物地理','The geobotany survey mapped alpine plants against elevation and soil moisture to explain why certain species occurred only on shaded slopes.','植物地理调查把高山植物分布与海拔、土壤湿度对应起来，解释为何某些物种只出现在背阴坡。','The geobotany survey mapped alpine plants against elevation and soil moisture / to explain / why certain species occurred only on shaded slopes.','geobotany 涉及植物分布与环境因素；to explain 引出调查目的。','研究植物的空间分布及环境联系，符合 geobotany。'),M('Geobotany studies only the private family histories of botanists and ignores plant distribution.','Genealogy studies family histories; geobotany studies plant distribution in relation to place and environment.','家族历史属于 genealogy，不是 geobotany。'),[Q('geobotany',1,1,'Geobotany links plant life with?','geography and environmental conditions','the history of court law','the design of electrical generators','geobotany 研究植物分布与地理环境。'),Q('geobotany',2,1,'A geobotanist might map?','where plant species grow at different elevations','where ships store food','how families inherit surnames only','绘制植物随海拔变化的分布图属于 geobotany。'),Q('geobotany',3,1,'Which question belongs to geobotany?','Why does this species grow only on the north-facing slope?','How much does a newspaper cost?','What is the third Greek letter?','物种为何分布于特定环境是植物地理问题。'),Q('geobotany',4,1,'Geobotany is closest to the combined study of?','plants and their geographic distribution','birds and courtroom procedure','genes and newspaper printing','geo 与 botany 结合指植物地理研究。')]);
P('geochemical','geochemical 由 geo- 与 chemical 构成，指地球物质的化学组成及发生在地球内部、表面或环境中的化学过程。',C('geochemical.s1','土壤检测','The geochemical survey measured trace metals in stream sediment to identify whether the upstream mine had released contaminants.','地球化学调查测量了溪流沉积物中的微量金属，以判断上游矿区是否排放污染物。','The geochemical survey measured trace metals in stream sediment / to identify / whether the upstream mine had released contaminants.','geochemical 修饰 survey，表明其研究地球材料的化学成分；whether 引出调查问题。','测量沉积物中的金属以研究地球化学组成。'),M('The geochemical survey recorded only bird songs and never analyzed rocks, soil, water, or chemical elements.','The acoustic survey recorded bird songs and never analyzed rocks, soil, water, or chemical elements.','录制鸟鸣属于声学调查，不是地球化学分析。'),[Q('geochemical',1,1,'A geochemical analysis examines?','chemical elements and processes in Earth materials','the grammar of a spoken language','the wing shape of a bird','geochemical 指地球物质化学组成与过程。'),Q('geochemical',2,1,'A geochemical map might show?','where certain minerals or elements occur in soil','where buses stop in a city','the family tree of a local poet','元素和矿物的空间分布属于地球化学资料。'),Q('geochemical',3,1,'Which sample might a geochemical team test?','river sediment for trace metals','a theater ticket for its seat number','a bird’s call for its melody','沉积物中的微量金属是地球化学研究对象。'),Q('geochemical',4,1,'The prefix geo- points to?','the Earth','a family','a musical instrument','geo- 表示地球或地理。')]);
P('geographer','geographer 由 geography 加施事者后缀 -er 构成，可指研究地表区域与人地特征的学者，也可指在学校教授地理的人。',C('geographer.s1','城市研究','The geographer compared housing maps with transit routes to explain how access to rail stations shaped the growth of the outer districts.','地理学家比较住房地图和公交路线，以解释铁路站点的可达性如何影响外围城区的发展。','The geographer compared housing maps with transit routes / to explain / how access to rail stations shaped the growth / of the outer districts.','geographer 指研究地理特征的专家；to explain 引出空间分析目的。','研究交通与城区空间发展的关系，符合学者义 s1。'),M('The geographer studied only inherited genes and never examined land, places, or spatial patterns.','The geneticist studied inherited genes, while the geographer examined places and spatial patterns.','遗传学研究基因；地理学家研究土地、区域和空间关系。'),[Q('geographer',1,1,'A geographer studies?','places, landscapes, and spatial patterns','only inherited DNA sequences','the construction of ship kitchens','geographer 研究地理空间与地表特征。'),Q('geographer',2,2,'At a school, a geographer may be someone who?','teaches geography to students','maps family ancestry for clients','measures the Earth’s magnetic field only','词条也收学校地理教师义 s2。'),Q('geographer',3,1,'Which project fits a geographer?','mapping how access to transit differs by neighborhood','testing a medicine’s dosage','studying only the grammar of Greek letters','比较不同社区的交通可达性属于地理研究。'),Q('geographer',4,1,'A geographer is closest to a?','geography specialist','genealogist','gallant sailor','geography specialist 即地理学者。')]);
P('geographic','geographic 由 geography 加 -ic 构成，可指地点的自然地理特征，也可指某种现象在不同地区的分布。',C('geographic.s2','区域分布','The company adjusted delivery fees by geographic region because remote islands faced higher transport costs than nearby cities.','公司按地理区域调整配送费，因为偏远岛屿的运输成本高于附近城市。','The company adjusted delivery fees by geographic region / because remote islands faced higher transport costs / than nearby cities.','geographic 修饰 region，指按地域划分；because 从句说明区域差异。','费用按不同地域调整，体现 geographic 的区域义 s2。'),M('The fee schedule was geographic because every customer paid the same price regardless of location.','The flat fee schedule ignored geographic differences because every customer paid the same price regardless of location.','不考虑位置差异的统一价格并未按地理区域划分。'),[Q('geographic',1,1,'A geographic feature of a place might be?','a mountain range or river system','the serial number of a phone','a person’s inherited eye color','地形和河流属于自然地理特征。'),Q('geographic',2,2,'A geographic pattern describes?','how something is distributed across regions','how an individual inherits one gene','how a sentence is punctuated','区域分布属于 geographic 的 s2。'),Q('geographic',3,1,'Which issue is geographic?','why one region receives less rainfall than another','whether a medicine’s dose is safe','which Greek letter follows beta','比较地区降雨差异属于地理问题。'),Q('geographic',4,2,'A geographic pricing plan may vary according to?','the customer’s location','the customer’s favorite color','the number of letters in a name','按地区调整价格体现地域分布。')]);
P('geographical','geographical 由 geography 加 -ical 构成，既可指地理学本身，也可描述地理范围、区位或区域分布。',C('geographical.s2','服务覆盖范围','The charity mapped the geographical distribution of its clinics and found that mountain communities had the least access to care.','慈善机构绘制了诊所的地域分布图，发现山区社区获得服务的机会最少。','The charity mapped the geographical distribution of its clinics / and found / that mountain communities had the least access to care.','geographical distribution 是常见搭配，指地域分布；that 从句呈现地图调查结果。','地图显示服务点在不同地区的分布及不均衡情况。'),M('The geographical map showed no locations and contained only a list of employee birthdays.','The staff calendar listed employee birthdays, while the geographical map showed clinic locations.','只列生日的日历不呈现地理分布。'),[Q('geographical',1,2,'A geographical distribution shows?','where something is located across regions','how a gene is inherited','which words rhyme in a poem','geographical 可指空间分布。'),Q('geographical',2,1,'Geographical research belongs to the study of?','geography and places','genetics and heredity','fencing and sport','geographical 可表示地理学的。'),Q('geographical',3,2,'A geographical barrier might be?','a mountain range separating two regions','a polite greeting at a door','a small ornament on a plate','山脉分隔地区，构成地理屏障。'),Q('geographical',4,1,'A geographical survey is most likely to record?','the locations and features of places','the exact sequence of DNA bases only','the flavor of a meal','地理调查记录地点及其特征。')]);
P('geologic','geologic 由 geology 加 -ic 构成，表示地质学的，或与地球漫长的物理演变历史有关。',C('geologic.s1','地球历史','The canyon’s layers preserve a geologic record of ancient floods, volcanic ash, and long periods when the region lay beneath the sea.','峡谷岩层保存了当地的地质记录，包括古洪水、火山灰以及该地区长期处于海底的时期。','The canyon’s layers preserve a geologic record / of ancient floods, volcanic ash, / and long periods / when the region lay beneath the sea.','geologic 修饰 record，指地质历史记录；of 后列举保存的事件和环境。','岩层记录地球在漫长时期内的变化，符合地质历史义。'),M('The geologic record covered only yesterday’s weather and had no information about the Earth’s past.','The daily weather record covered yesterday’s conditions and had no information about the Earth’s past.','短期天气记录不是地球漫长演变的地质记录。'),[Q('geologic',1,1,'A geologic record preserves evidence about?','the physical history of the Earth','the daily schedule of a school','the ancestry of one family','geologic 可指地球的长期历史。'),Q('geologic',2,1,'A geologic map may show?','rock formations and faults','the seating plan for a theater','a list of election candidates','岩层与断层是地质图所示内容。'),Q('geologic',3,1,'A change over geologic time happens?','over extremely long periods in Earth history','in a few seconds during a phone call','only during one afternoon','geologic time 指极漫长的地球历史尺度。'),Q('geologic',4,1,'The closest field to geologic study is?','geology','genealogy','geometry','geology 是地质学。')]);
P('geological','geological 是 geology 加 -ical 构成的形容词，可描述岩石与地质学，也可形容跨越极漫长地质年代的过程。',C('geological.s2','时间尺度','Although the valley looks stable today, the river’s geological evolution took place over millions of years as the surrounding plateau rose and eroded.','尽管山谷如今看似稳定，但随着周围高原抬升和侵蚀，河谷经历了数百万年的地质演变。','Although the valley looks stable today / the river’s geological evolution took place over millions of years / as the surrounding plateau rose and eroded.','geological 修饰 evolution；over millions of years 强调 s2 的漫长时间尺度。','地貌演变持续数百万年，体现地质年代义。'),M('The geological evolution of the valley took place in a single afternoon and ended before sunset.','The rapid erosion of the valley took place after heavy rain and ended before sunset.','地质演变通常以极长时间计，不是一下午完成。'),[Q('geological',1,2,'A geological timescale is measured in?','very long periods, often millions of years','seconds on a stopwatch','the number of pages in a report','geological 可指极漫长时间尺度。'),Q('geological',2,1,'A geological survey might examine?','rocks, faults, and layers beneath the surface','the manners of a formal dinner','the route of a city bus only','岩石、断层和地层属于地质调查。'),Q('geological',3,2,'A geological process may reshape a landscape?','over millions of years','only during one brief conversation','without any physical change','地貌地质过程常跨越漫长年代。'),Q('geological',4,1,'Which phrase is natural?','geological evidence of an ancient volcano','geological of the ancient volcano evidence','geologically evidence of ancient volcano','形容词 geological 可修饰 evidence。')]);
P('geologically','geologically 由 geological 加 -ly 构成，表示从地质学角度、按地质条件或以地质年代尺度而言。',C('geologically.s1','区域对比','The two islands are geologically similar, with matching basalt layers, even though their climates and plant communities are quite different.','这两座岛在地质上相似，都有对应的玄武岩层，尽管气候和植物群落截然不同。','The two islands are geologically similar / with matching basalt layers / even though their climates and plant communities / are quite different.','geologically 修饰 similar，限定比较角度为地质；even though 对照其他差异。','相同玄武岩层说明地质特征相似。'),M('The islands are geologically identical because their residents speak the same language.','The islands are culturally similar because their residents speak the same language.','语言相同是文化相似的证据，不能说明地质相同。'),[Q('geologically',1,1,'Two sites are geologically close if they are similar in?','rocks, structures, or Earth processes','the politeness of their residents','the color of their street signs','geologically 指从地质学角度。'),Q('geologically',2,1,'A geologist studies a landscape geologically by?','examining its rocks and physical history','counting its local newspaper readers','asking only how warm its cafes feel','分析岩石和地球物理历史属于地质学视角。'),Q('geologically',3,1,'A region can be geologically stable while?','its economy changes rapidly','its rocks cease to exist','its geology becomes a family tree','地质稳定与经济迅速变化可以同时存在。'),Q('geologically',4,1,'Which word does geologically modify in “geologically young rock”?','young','rock only as a noun label','the speaker’s voice','geologically 修饰形容词 young，限定其地质时间含义。')]);
P('geologist','geologist 由 geology 加 -ist 构成，指研究岩石和地球的科学家，也可指在野外勘察矿物或油气资源的人。',C('geologist.s2','野外勘查','The field geologist mapped the exposed rock layers and collected samples to assess whether the valley contained a viable mineral deposit.','野外地质勘探员绘制了裸露岩层，并采集样本，以评估山谷是否有可开发的矿床。','The field geologist mapped the exposed rock layers / and collected samples / to assess whether the valley contained / a viable mineral deposit.','field geologist 可指野外勘探人员；to assess 表明其资源勘察目的。','绘图采样并评估矿藏，符合现场勘查义 s2。'),M('The geologist surveyed the valley by measuring bird songs and never examined any rocks or landforms.','The ornithologist surveyed bird songs, while the geologist examined rocks and landforms.','研究鸟类声音属于鸟类学，不是地质学。'),[Q('geologist',1,1,'A geologist studies?','rocks and the physical Earth','family relationships across generations','the grammar of Greek letters','geologist 研究岩石和地球。'),Q('geologist',2,2,'A field geologist may survey land to?','locate minerals or oil-bearing formations','teach a school geography lesson only','repair a ship’s kitchen','s2 指野外勘查矿物或油气。'),Q('geologist',3,1,'Which tool might a geologist use in the field?','a rock hammer and geological map','a chef’s knife and dinner menu','a fencing foil and mask','野外地质工作常用岩锤和地质图。'),Q('geologist',4,1,'A geologist’s report might describe?','the age and composition of rock layers','the manners of the local gentry','a recipe’s seasoning','岩层年代和成分属于地质报告内容。')]);
P('geomagnetic','geomagnetic 由 geo- 与 magnetic 组成，表示地球磁场或地磁现象相关的。',C('geomagnetic.s1','地球物理监测','The geomagnetic observatory tracked small changes in the Earth’s magnetic field and compared them with readings from stations farther north.','地磁观测站追踪地球磁场的微小变化，并将其与更北方站点的读数比较。','The geomagnetic observatory tracked small changes / in the Earth’s magnetic field / and compared them with readings / from stations farther north.','geomagnetic 修饰 observatory，说明观测对象为地磁；compared 引出跨站数据比较。','站点测量地球磁场变化，符合 geomagnetic。'),M('The geomagnetic survey measured only the sweetness of soil and did not observe any magnetic field.','The agricultural survey measured soil nutrients and did not observe any magnetic field.','测土壤甜度不涉及地磁现象。'),[Q('geomagnetic',1,1,'Geomagnetic refers to?','the Earth’s magnetism','the Earth’s family history','the shape of a flower wreath','geomagnetic 表示地磁的。'),Q('geomagnetic',2,1,'A geomagnetic storm affects?','conditions related to Earth’s magnetic field','the legal wording of a gazette','the temperature inside a bird nest','地磁暴与地球磁场相关。'),Q('geomagnetic',3,1,'Which instrument reading is geomagnetic data?','a measurement of magnetic-field direction near Earth','a count of plants in a garden','a record of family births','测量地球附近磁场方向属于地磁数据。'),Q('geomagnetic',4,1,'The prefix geo- in geomagnetic refers to?','Earth','a person’s genes','a Greek letter','geo- 表示地球。')]);
P('geometric','geometric 由 geometry 加 -ic 构成，可指几何学或几何形状，也可指按固定乘数逐步增加的几何级数增长。',C('geometric.s3','数量增长','The bacteria count showed geometric growth, doubling at each step rather than increasing by the same fixed number.','细菌数量呈几何级数增长，每一步都翻倍，而不是每次增加相同的固定数目。','The bacteria count showed geometric growth / doubling at each step / rather than increasing / by the same fixed number.','geometric 修饰 growth，s3 指每步乘以固定倍数；rather than 对比算术式增量。','每次翻倍而非等量增加，符合几何增长义。'),M('The sequence grew geometrically by adding exactly one cell at every step.','The sequence grew arithmetically by adding exactly one cell at every step.','每步增加固定数量是算术增长，不是几何增长。'),[Q('geometric',1,1,'A geometric proof uses?','the principles and rules of geometry','a family tree and birth records','a list of gaslit theaters','几何证明使用几何学规则。'),Q('geometric',2,2,'A geometric pattern might be made of?','repeating triangles, circles, and straight lines','random stains with no shapes','only spoken words','几何图案由规则线条和形状构成。'),Q('geometric',3,3,'Geometric growth occurs when a quantity?','is multiplied by a constant factor at each step','increases by the same fixed amount each step','never changes at all','每步乘以固定倍数是几何增长。'),Q('geometric',4,1,'A geometric angle is studied in?','geometry','genetics','geobotany','angle 的几何性质属于 geometry。')]);
P('geometrical','geometrical 由 geometry 加 -ical 构成，是 geometric 的对应形容词，表示几何学的或由规则几何形状组成的。',C('geometrical.s1','数学课堂','The teacher used a geometrical construction to show how the perpendicular bisector of a segment passes through points equally distant from both ends.','教师用几何作图说明线段的垂直平分线经过到两端距离相等的点。','The teacher used a geometrical construction / to show / how the perpendicular bisector of a segment passes / through points equally distant from both ends.','geometrical 修饰 construction，表示几何作图；how 从句说明构造的数学性质。','垂直平分线作图展示几何规则，符合词义。'),M('The geometrical proof relied on family birth records instead of shapes, lines, or mathematical relations.','The genealogical study relied on family birth records instead of shapes, lines, or mathematical relations.','家族出生记录属于 genealogy，不是几何证明。'),[Q('geometrical',1,1,'A geometrical figure is made from?','regular lines, angles, or shapes','family names and birth dates','gas lamps and fuel tanks','几何图形由线、角和形状构成。'),Q('geometrical',2,1,'A geometrical construction is?','a drawing made according to mathematical rules','a list of historical court cases','a recipe for a flower garnish','按数学规则作图属于 geometrical construction。'),Q('geometrical',3,1,'Which object has a geometrical design?','a tile patterned with regular hexagons','a cloud with changing irregular edges','a page of unrelated spoken notes','规则六边形构成几何图案。'),Q('geometrical',4,1,'Geometrical is closest in meaning to?','geometric','garrulous','geochemical','geometrical 与 geometric 意义接近。')]);
P('geometrically','geometrically 由 geometrical 加 -ly 构成，可表示按照几何规则，也可表示数量以固定倍数递增。',C('geometrically.s1','空间布局','The designer arranged the lamps geometrically, spacing them at equal intervals along concentric circles around the central platform.','设计师按几何方式布置灯具，让它们沿以中央平台为圆心的同心圆等距排列。','The designer arranged the lamps geometrically / spacing them at equal intervals / along concentric circles / around the central platform.','geometrically 修饰 arranged，说明布局遵循圆形和等距规则。','灯具依照同心圆的几何规则布置，符合 s1。'),M('The lamps were spaced geometrically by placing them randomly at unequal distances without any pattern.','The lamps were spaced randomly by placing them at unequal distances without any pattern.','没有规律且间距不等属于随机布置，不是几何排列。'),[Q('geometrically',1,1,'To arrange objects geometrically is to place them?','according to geometric shapes or rules','by guessing with no pattern','according to their family histories','geometrically 可表示按几何规则排列。'),Q('geometrically',2,1,'A geometrically increasing sequence may?','multiply by the same factor at each step','add one fixed unit each time only','alternate randomly with no rule','副词也可表示按几何级数增长。'),Q('geometrically',3,1,'Which arrangement is geometrically regular?','lights equally spaced around a circle','chairs scattered at random','books piled in an uneven heap','沿圆周等距放置符合几何规律。'),Q('geometrically',4,1,'In “the number grows geometrically,” geometrically most likely describes?','multiplication by a constant ratio','a drawing made with a ruler','a change in location across regions','geometric growth 是每步乘固定比率。')]);
P('geophysical','geophysical 由 geo- 与 physical 组成，指研究地球物理性质和过程的，涉及重力、地震、热流或磁场等现象。',C('geophysical.s1','地震勘测','The geophysical survey used seismic waves to map layers beneath the proposed tunnel route before engineers selected a safe alignment.','在工程师确定安全线路前，地球物理勘测利用地震波绘制了拟建隧道路线下方的地层。','The geophysical survey used seismic waves / to map layers beneath the proposed tunnel route / before engineers selected / a safe alignment.','geophysical 修饰 survey，指利用地球物理方法勘测；before 从句说明勘测用于前期选线。','地震波用于探测地下物理结构，属于地球物理勘测。'),M('The geophysical survey studied only family pedigrees and never measured any physical property of the Earth.','The genealogical survey studied family pedigrees and did not measure physical properties of the Earth.','家系调查属于谱系研究，并非地球物理勘测。'),[Q('geophysical',1,1,'Geophysical research concerns?','the physical properties and processes of the Earth','the manners of a formal dinner','the production of newspaper notices','geophysical 指地球的物理性质与过程。'),Q('geophysical',2,1,'A geophysical survey may use seismic waves to?','investigate underground layers','decorate a garden with flowers','record the speech of a witness','地震波可探测地下结构。'),Q('geophysical',3,1,'Which topic is geophysical?','how gravity varies across a mountain range','how a family inherited a surname','how a gannet catches fish','重力随地形的变化是地球物理议题。'),Q('geophysical',4,1,'The prefix geo- in geophysical means?','Earth','gene','general','geo- 表示地球。')]);

})();
